#include <iostream>

class Node {
public:
    char key;
    int frequency;
    Node* next;

    Node(char key, int frequency) {
        this->key = key;
        this->frequency = frequency;
        this->next = nullptr;
    }
};

class HashTable {
private:
    Node** table;
    int size;

    int hash(char key) {
        return key % size;
    }

public:
    HashTable(int size) {
        this->size = size;
        this->table = new Node*[size];
        for (int i = 0; i < size; i++) {
            table[i] = nullptr;
        }
    }

    ~HashTable() {
        for (int i = 0; i < size; i++) {
            Node* current = table[i];
            while (current != nullptr) {
                Node* temp = current;
                current = current->next;
                delete temp;
            }
        }
        delete[] table;
    }

    void insert(char key) {
        int index = hash(key);
        if (table[index] == nullptr) {
            table[index] = new Node(key, 1);
        } else {
            Node* current = table[index];
            while (current != nullptr) {
                if (current->key == key) {
                    current->frequency++;
                    return;
                }
                if (current->next == nullptr) {
                    break;
                }
                current = current->next;
            }
            current->next = new Node(key, 1);
        }
    }

    int getFrequency(char key) {
        int index = hash(key);
        Node* current = table[index];
        while (current != nullptr) {
            if (current->key == key) {
                return current->frequency;
            }
            current = current->next;
        }
        return 0;
    }
};

void findCharacterFrequency(const std::string& input) {
    int size = 26; // Number of alphabets
    HashTable hashtable(size);

    for (char c : input) {
        if (isalpha(c)) { // Ignore non-alphabetic characters
            char lowercase = tolower(c); // Treat case sensitivity
            hashtable.insert(lowercase);
        }
    }

    for (char c = 'a'; c <= 'z'; c++) {
        int frequency = hashtable.getFrequency(c);
        if (frequency > 0) {
            std::cout << "'" << c << "' frequency: " << frequency << std::endl;
        }
    }
}

int main() {
    std::string input = "AbcAB";
    findCharacterFrequency(input);
    return 0;
}
```

This implementation uses a hash table with separate chaining to store the frequencies of each character in the input string. The hash table is implemented as an array of linked lists, where each element in the array represents a slot in the hash table, and each linked list stores the characters that hash to that slot.

The `Node` class represents a node in the linked list, with a `key` to store the character and a `frequency` to store the frequency of that character. The `HashTable` class represents the hash table itself, with methods to insert a character and get its frequency.

The `findCharacterFrequency` function takes a string as input, iterates over each character, ignores non-alphabetic characters, treats case sensitivity, and inserts the characters into the hash table. Finally, it prints the frequency of each character that occurred in the input string.

To optimize memory usage, the hash table is initialized with a fixed size equal to the number of alphabetic characters. This way, it only reserves space for the characters that actually occur in the string.

