To calculate the total working hours between the given dates, you can define a function that takes into account varying business hours for different days of the week and any additional time off during holidays. Here's an example:

```javascript
const moment = require('moment-timezone');
require('moment-business-days');
require('moment-timezone');

// Set the start and end dates with time zone information
const startDate = moment.tz('2021-07-01', 'America/New_York');
const endDate = moment.tz('2021-07-10', 'America/New_York');

// Define business hours for each day of the week
const businessHours = {
  Monday: { start: '09:00', end: '17:00' },
  Tuesday: { start: '09:00', end: '17:00' },
  Wednesday: { start: '09:00', end: '17:00' },
  Thursday: { start: '09:00', end: '17:00' },
  Friday: { start: '09:00', end: '17:00' },
};

// Define additional time off for holidays
const holidays = {
  '2021-07-04': { start: '00:00', end: '23:59' }, // Example holiday on July 4th, 2021
};

// Calculate the total working hours between the dates
function calculateWorkingHours(startDate, endDate, businessHours, holidays) {
  let totalHours = 0;
  let currentDate = startDate.clone();

  while (currentDate.isSameOrBefore(endDate, 'day')) {
    const dayOfWeek = currentDate.format('dddd');

    // Exclude weekends and holidays
    if (currentDate.isBusinessDay() && !holidays[currentDate.format('YYYY-MM-DD')]) {
      const { start, end } = businessHours[dayOfWeek];
      const startDateTime = moment.tz(currentDate.format('YYYY-MM-DD') + ' ' + start, 'America/New_York');
      const endDateTime = moment.tz(currentDate.format('YYYY-MM-DD') + ' ' + end, 'America/New_York');

      // Calculate working hours for the day
      const hours = endDateTime.diff(startDateTime, 'hours');

      totalHours += hours;
    }

    // Move to the next day
    currentDate.add(1, 'day');
  }

  return totalHours;
}

const workingHours = calculateWorkingHours(startDate, endDate, businessHours, holidays);

console.log('Total working hours:', workingHours);
```

Note: Make sure to install the required libraries (`moment`, `moment-business-days`, and `moment-timezone`) using npm or yarn before running the code.

