function getCurrentDateTime() {
  var currentDate = new Date();
  var timeZoneOffset = currentDate.getTimezoneOffset() / 60;

  // Adjusting for time zone offset
  currentDate.setHours(currentDate.getHours() + timeZoneOffset);

  // Adjusting for daylight saving time changes
  var dstStart = new Date(currentDate.getFullYear(), 2, 14);
  dstStart.setDate(14 - dstStart.getDay() + 1);
  var dstEnd = new Date(currentDate.getFullYear(), 10, 7);
  dstEnd.setDate(7 - dstEnd.getDay() + 1);
  var dstActive = currentDate >= dstStart && currentDate < dstEnd;

  if (dstActive) {
    currentDate.setHours(currentDate.getHours() + 1);
  }

  // Getting date and time components
  var year = currentDate.getFullYear();
  var month = addLeadingZero(currentDate.getMonth() + 1);
  var day = addLeadingZero(currentDate.getDate());
  var hours = addLeadingZero(currentDate.getHours());
  var minutes = addLeadingZero(currentDate.getMinutes());
  var seconds = addLeadingZero(currentDate.getSeconds());
  var ampm = currentDate.getHours() >= 12 ? 'PM' : 'AM';

  // Constructing the formatted date and time string
  var formattedDateTime = year + '-' + month + '-' + day + ' ' + hours + ':' + minutes + ':' + seconds + ' ' + ampm;

