```javascript
function extractText(element) {
  // Initialize an empty string to store the extracted text
  let text = '';

  // Iterate over each child node of the given element
  for (let i = 0; i < element.childNodes.length; i++) {
    const node = element.childNodes[i];

    // Check the node type
    switch (node.nodeType) {
      // If it's a text node, append the text content to the result string
      case Node.TEXT_NODE:
        text += node.textContent.trim();
        break;

      // If it's an element node, recursively call the function on the child element
      case Node.ELEMENT_NODE:
        text += extractText(node);
        break;

      // Ignore other node types (e.g., comments, processing instructions)
      default:
        break;
    }
  }

  // Return the extracted text
  return text;
}
