    const num = parseInt(alphanumericArr[i]);

    // Check if the number is prime and not already in the uniquePrimes array
    if (isPrime(num) && !uniquePrimes.includes(num)) {
      uniquePrimes.push(num);
    }
  }

  // Sort the unique prime numbers in ascending order
