function validateUsername(username) {
  // Check the length of the username
  if (username.length < 8 || username.length > 16) {
    return false;
  }

  // Check if the username starts with a letter
  if (!/^[a-zA-Z]/.test(username)) {
    return false;
  }

  // Check if the username ends with an underscore or hyphen
  if (/[_-]$/.test(username)) {
    return false;
  }

  // Check if the username contains consecutive underscores or hyphens
  if (/[_-]{2}/.test(username)) {
    return false;
  }

  // Check if the username contains repeating patterns of characters of length 4 or more
  if (/(.+)\1{3}/.test(username)) {
    return false;
  }

  // Check if the username contains sequential patterns of characters of length 5 or more
  if (/([a-zA-Z0-9]{5,})/.test(username)) {
    const sequence = RegExp.$1;
    if (sequence === 'abcdefghijklmnopqrstuvwxyz' || sequence === 'ABCDEFGHIJKLMNOPQRSTUVWXYZ' || sequence === '01234567890') {
      return false;
    }
  }

  // Check if the username contains palindromic patterns of characters of length 3 or more
  if (/(\w{3,}).*\1/.test(username)) {
    return false;
  }

  // All checks passed, username is valid
  return true;
}

