function fadeIn(element, duration, options) {
  var start = performance.now();
  var isVisible = element.style.opacity === "1";
  var callback = options && options.callback;
  var delay = options && options.delay || 0;
  var easingFunction = options && options.easingFunction || linear;

  if (!isVisible) {
    element.style.transition = "opacity " + duration + "ms " + easingFunction;
    element.style.opacity = "1";
  }

  var animation = {
    pause: function() {
      element.style.transition = "";
      element.style.opacity = window.getComputedStyle(element).opacity;
    },
    resume: function() {
      var remainingTime = duration - (performance.now() - start);
      element.style.transition = "opacity " + remainingTime + "ms " + easingFunction;
      element.style.opacity = "1";
    }
  };

  if (delay) {
    setTimeout(startAnimation, delay);
  } else {
    startAnimation();
  }

  function startAnimation() {
    element.style.transition = "opacity " + duration + "ms " + easingFunction;
    element.style.opacity = "1";
    var animationEnd = performance.now() + duration;
    var animationTimeout;

    if (callback) {
      animationTimeout = setTimeout(callback, duration);
    }

    animation.pause = function() {
      clearTimeout(animationTimeout);
      var remainingTime = animationEnd - performance.now();
      element.style.transition = "";
      element.style.opacity = window.getComputedStyle(element).opacity;
      clearTimeout(animationTimeout);
      duration = remainingTime;
    };

    animation.resume = function() {
      start = performance.now() - (duration - remainingTime);
      element.style.transition = "opacity " + duration + "ms " + easingFunction;
      element.style.opacity = "1";
      animationTimeout = setTimeout(callback, duration);
    };
  }

  return animation;
}

function fadeOut(element, duration, options) {
