  if (num <= 1) return false;
  if (num <= 3) return true;

  if (num % 2 === 0 || num % 3 === 0) return false;

  let i = 5;
  while (i * i <= num) {
    if (num % i === 0 || num % (i + 2) === 0) return false;
    i += 6;
  }

  return true;
}

// Function to check if the range is consecutive prime numbers
function isConsecutivePrimeRange(lowerBound, upperBound) {
  let isConsecutive = true;

  for (let i = lowerBound + 1; i < upperBound; i++) {
    if (!isPrime(i)) {
      isConsecutive = false;
      break;
    }
  }

  return isConsecutive;
}

// Function to check if a number is within the given range
function isInRange(number, lowerBound, upperBound) {
  if (isPrime(lowerBound) && isPrime(upperBound) && isConsecutivePrimeRange(lowerBound, upperBound)) {
    return number >= lowerBound && number <= upperBound;
  }

  return false;
}

