function longestCommonSubsequence(sequence1, sequence2) {
  const m = sequence1.length;
  const n = sequence2.length;
  const dp = [];

  // Initialize the dp array
  for (let i = 0; i <= m; i++) {
    dp[i] = [];
    for (let j = 0; j <= n; j++) {
      dp[i][j] = 0;
    }
  }

  // Compute the length of the longest common subsequence
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (sequence1[i - 1] === sequence2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }

  // Backtrack to find the longest common subsequence
  const longestSubsequence = [];
  let i = m;
  let j = n;
  while (i > 0 && j > 0) {
    if (sequence1[i - 1] === sequence2[j - 1]) {
      longestSubsequence.unshift(sequence1[i - 1]);
      i--;
      j--;
    } else if (dp[i - 1][j] > dp[i][j - 1]) {
      i--;
    } else {
      j--;
    }
  }

  return longestSubsequence;
}

