var table = document.getElementById("studentTable");
var rows = table.getElementsByTagName("tr");
var pagination = document.getElementById("pagination");
var pageSize = 5;
var currentPage = 1;

// Sort table based on selected column
function sortTable(column) {
  var rowsArray = Array.prototype.slice.call(rows, 1);

  rowsArray.sort(function(a, b) {
    var aData = a.getElementsByTagName("td")[column].innerHTML;
    var bData = b.getElementsByTagName("td")[column].innerHTML;
    return aData.localeCompare(bData);
  });

  if (rows[column].classList.contains("asc")) {
    rowsArray.reverse();
    rows[column].classList.remove("asc");
    rows[column].classList.add("desc");
  } else {
    rows[column].classList.remove("desc");
    rows[column].classList.add("asc");
  }

  for (var i = 0; i < rowsArray.length; i++) {
    table.tBodies[0].appendChild(rowsArray[i]);
  }
}

// Search table for matching rows
function searchTable() {
  var input = document.getElementById("searchInput");
  var filter = input.value.toUpperCase();

  for (var i = 0; i < rows.length; i++) {
    var cells = rows[i].getElementsByTagName("td");
    var match = false;

    for (var j = 0; j < cells.length; j++) {
      if (cells[j].innerHTML.toUpperCase().indexOf(filter) > -1) {
        match = true;
        break;
      }
    }

    if (match) {
      rows[i].style.display = "";
    } else {
      rows[i].style.display = "none";
    }
  }

  currentPage = 1;
  generatePagination();
}

// Generate pagination controls
function generatePagination() {
  var totalRows = rows.length - 1;
  var totalPages = Math.ceil(totalRows / pageSize);
  var startPage, endPage;

  if (totalPages <= 5) {
    startPage = 1;
    endPage = totalPages;
  } else {
    if (currentPage <= 3) {
      startPage = 1;
      endPage = 5;
    } else if (currentPage + 1 >= totalPages) {
      startPage = totalPages - 4;
      endPage = totalPages;
    } else {
      startPage = currentPage - 2;
      endPage = currentPage + 2;
    }
  }

  pagination.innerHTML = "";

  var prevButton = document.createElement("span");
  prevButton.innerHTML = "Prev";

  if (currentPage === 1) {
    prevButton.classList.add("disabled");
  } else {
    prevButton.addEventListener("click", function() {
      currentPage--;
      generatePagination();
    });
  }

  pagination.appendChild(prevButton);

  for (var i = startPage; i <= endPage; i++) {
    var pageButton = document.createElement("span");
    pageButton.innerHTML = i;

    if (i === currentPage) {
      pageButton.classList.add("active");
    } else {
      pageButton.addEventListener("click", function() {
        currentPage = parseInt(this.innerHTML);
        generatePagination();
      });
    }

    pagination.appendChild(pageButton);
  }

  var nextButton = document.createElement("span");
  nextButton.innerHTML = "Next";

  if (currentPage === totalPages) {
    nextButton.classList.add("disabled");
  } else {
    nextButton.addEventListener("click", function() {
      currentPage++;
      generatePagination();
    });
  }

  pagination.appendChild(nextButton);

  showRows();
}

// Show rows for current page
function showRows() {
  for (var i = 0; i < rows.length; i++) {
    if (i >= pageSize * (currentPage - 1) + 1 && i <= pageSize * currentPage) {
      rows[i].style.display = "";
    } else {
      rows[i].style.display = "none";
    }
  }
}

// Initial setup
generatePagination();
```

