public class PrimeMultiplicationTable {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("Welcome to the Prime Multiplication Table Generator!");
        System.out.print("Please enter the number of rows and columns for the table: ");
        int size = scanner.nextInt();

        while (size <= 0) {
            System.out.print("Invalid input. Please enter a positive integer for the size: ");
            size = scanner.nextInt();
        }

        System.out.println("Choose an option:");
        System.out.println("1. Prime Numbers Only");
        System.out.println("2. All Numbers");
        System.out.print("Option: ");
        int option = scanner.nextInt();

        while (option < 1 || option > 2) {
            System.out.print("Invalid option. Please enter 1 or 2: ");
            option = scanner.nextInt();
        }

        int[][] multiplicationTable = generateMultiplicationTable(size, option);

        displayTable(multiplicationTable);

        System.out.print("Do you want to save the table to a file? (y/n): ");
        String saveOption = scanner.next().toLowerCase();

        if (saveOption.equals("y")) {
            saveTableToFile(multiplicationTable);
        }

        scanner.close();
    }

    public static int[][] generateMultiplicationTable(int size, int option) {
        int[][] table = new int[size][size];

        for (int i = 1; i <= size; i++) {
            for (int j = 1; j <= size; j++) {
                int value = i * j;

                if (option == 1 && isPrime(value)) {
                    table[i-1][j-1] = value;
                } else if (option == 2) {
                    table[i-1][j-1] = value;
                }
            }
        }

        return table;
    }

    public static boolean isPrime(int number) {
        if (number <= 1) {
            return false;
        }

        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }

        return true;
    }

    public static void displayTable(int[][] table) {
        int size = table.length;

        System.out.println("\nMultiplication Table\n");

        for (int i = 0; i <= size; i++) {
            for (int j = 0; j <= size; j++) {
                if (i == 0 && j == 0) {
                    System.out.print("\t");
                } else if (i == 0) {
                    System.out.print(j + "\t");
                } else if (j == 0) {
                    System.out.print(i + "\t");
                } else {
                    System.out.print(table[i-1][j-1] + "\t");
                }
            }
            System.out.println();
        }
    }

    public static void saveTableToFile(int[][] table) {
        try {
            PrintWriter writer = new PrintWriter(new FileWriter("multiplication_table.txt"));

            int size = table.length;

            writer.println("Multiplication Table");

            for (int i = 0; i <= size; i++) {
                for (int j = 0; j <= size; j++) {
                    if (i == 0 && j == 0) {
                        writer.print("\t");
                    } else if (i == 0) {
                        writer.print(j + "\t");
                    } else if (j == 0) {
                        writer.print(i + "\t");
                    } else {
                        writer.print(table[i-1][j-1] + "\t");
                    }
                }
                writer.println();
            }

            writer.close();

            System.out.println("Table saved successfully to multiplication_table.txt.");
        } catch (IOException e) {
            System.out.println("An error occurred while saving the table.");
        }
    }
}

