function removeVowels(str) {
  let vowels = 'aeiouAEIOU';
  let punctuationMarks = '!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~';

  let result = '';
  let prevChar = '';

  for (let i = 0; i < str.length; i++) {
    let char = str[i];

    // Preserve whitespace characters
    if (char === ' ') {
      result += char;
      continue;
    }

    // Preserve hyphen character
    if (char === '-') {
      result += char;
      prevChar = char;
      continue;
    }

    // Preserve non-ASCII characters
    if (char.charCodeAt(0) >= 128) {
      result += char;
      prevChar = char;
      continue;
    }

    // Remove vowels
    if (vowels.includes(char)) {
      continue;
    }

    // Remove punctuation marks (except hyphen)
    if (punctuationMarks.includes(char) && char !== '-') {
      continue;
    }

    // Preserve original case of letters
    if (prevChar === prevChar.toUpperCase()) {
      result += char.toUpperCase();
    } else {
      result += char.toLowerCase();
    }

    prevChar = char;
  }

  return result;
}
