function addNumbers(a, b) {
  if (!Number.isInteger(a) || !Number.isInteger(b) || a <= 1 || b <= 1) {
    throw new Error('Both numbers should be positive integers greater than 1.');
  }

  const sum = a + b;

  if (isPrime(sum)) {
    return sum * 2;
  } else {
    return sum / 2;
  }
}

function isPrime(num) {
  if (num === 2) {
    return true;
  }
  if (num <= 1 || num % 2 === 0) {
    return false;
  }

  for (let i = 3; i <= Math.sqrt(num); i += 2) {
    if (num % i === 0) {
      return false;
    }
  }

  return true;
}
```

Explanation:
- The function "addNumbers" takes two parameters, "a" and "b", which are checked for validity as positive integers greater than 1. If any of the conditions are not met, an error is thrown.
- The sum of the two numbers is calculated and stored in the "sum" variable.
- The function "isPrime" is used to check if the sum is a prime number. It checks for numbers less than or equal to 1, even numbers (except 2), and then checks for divisibility from 3 up to the square root of the number. If the number is divisible by any of these, it is not prime.
- If the sum is prime, the function returns the sum multiplied by 2. Otherwise, it returns the sum divided by 2.

The "addNumbers" function and the "isPrime" helper function together provide the required functionality to calculate the sum of two positive integers, validate the inputs, and determine if the sum is a prime number, all while being optimized for performance.

