  const [dateRange, setDateRange] = useState(false);
  const [csrfToken, setCsrfToken] = useState("");
  const [loading, setLoading] = useState(true);
  const [timer, setTimer] = useState(10);
  const [timerExpired, setTimerExpired] = useState(false);

  useEffect(() => {
    // Simulating API calls to fetch authentication status, permissions, and date range
    setTimeout(() => {
      setAuthenticated(true);
      setLoading(false);
    }, 1000);

    setTimeout(() => {
      setPermissions(true);
      setLoading(false);
    }, 2000);

    setTimeout(() => {
      setDateRange(true);
      setLoading(false);
    }, 3000);

    // Simulating API call to fetch CSRF token
    setTimeout(() => {
      const csrfToken = "sample-csrf-token";
      setCsrfToken(csrfToken);
    }, 4000);
  }, []);

  const handleButtonClick = () => {
    if (timer > 0) {
      alert("Button clicked before timer expired");
    } else {
      setTimerExpired(true);
    }
  };

  const handleTokenExpiration = () => {
    // Simulating token refresh API call
