      return <div>Loading...</div>;
    } else if (!authenticated) {
      return <div>Unauthorized</div>;
    } else if (!dateRange) {
      return <div>Out of Range</div>;
    } else if (!permissions) {
      return <div>Expired Session</div>;
    } else if (timerExpired) {
      return <div>Timer expired</div>;
    } else {
      return (
        <button onClick={handleButtonClick} disabled={timerExpired}>
          Click Me
        </button>
      );
    }
  };

  useEffect(() => {
    if (timer > 0 && !timerExpired) {
      const interval = setInterval(() => {
        setTimer((prevTimer) => prevTimer - 1);
      }, 1000);
      return () => clearInterval(interval);
    } else if (timer === 0 && !timerExpired) {
      setTimerExpired(true);
    }
  }, [timer, timerExpired]);

  useEffect(() => {
    if (timerExpired) {
      // Disable button when timer expires
      document.getElementById("button").disabled = true;
    }
  }, [timerExpired]);

  useEffect(() => {
