function groupAndSumObjectsByProperty(arr, property, threshold = 0) {
  // Create an empty object to store the grouped objects
  const groupedObjects = {};

  // Group the objects based on the specified property
  arr.forEach((obj) => {
    const department = obj[property];

    // If the department is not already present in the groupedObjects, create a new entry
    if (!groupedObjects[department]) {
      groupedObjects[department] = {
        department,
        sum: 0,
      };
    }

    // Sum up the values of the objects whose salary is above the threshold
    if (obj.salary > threshold) {
      groupedObjects[department].sum += obj.salary;
    }
  });

  // Convert the object into an array
  const groupedArray = Object.values(groupedObjects);

  // Sort the groups in descending order based on the sum of values
  groupedArray.sort((a, b) => {
    if (a.sum === b.sum) {
      // If two groups have the same sum of values, sort them alphabetically based on the department name
      return a.department.localeCompare(b.department);
    } else {
      return b.sum - a.sum;
    }
  });

  return groupedArray;
}

