function getCurrentDateTime(timezone) {
  try {
    // Get current date and time
    let currentDate = new Date();

    // Check if timezone is provided
    if (timezone) {
      // Convert to provided timezone
      currentDate = convertToTimezone(currentDate, timezone);
    }

