    return 'Error retrieving current date and time.';
  }
}

function convertToTimezone(date, timezone) {
  try {
    // Check if timezone is valid
    if (!Intl || !Intl.DateTimeFormat().resolvedOptions().timeZone.includes(timezone)) {
      throw new Error('Invalid timezone provided.');
    }

    // Convert to provided timezone
    const options = {
      timeZone: timezone,
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: 'numeric',
      minute: 'numeric',
      hour12: true
    };
    const formatter = new Intl.DateTimeFormat(undefined, options);
    const formattedDateTime = formatter.format(date);

    return new Date(formattedDateTime);
  } catch (error) {
    // Handle invalid timezone or conversion errors
    console.error('Error converting date and time to specified timezone:', error);
    throw new Error('Error converting date and time to specified timezone.');
  }
}
