function calculate(array) {
  // Remove non-numeric values
  let numericArray = array.filter(element => typeof element === 'number');

  // Sort the numeric values in ascending order
  numericArray.sort((a, b) => a - b);

  // Calculate the median
  let length = numericArray.length;
  let median;

  if (length % 2 === 0) {
    // If the array has an even length, calculate the average of the two middle elements
    median = (numericArray[length / 2 - 1] + numericArray[length / 2]) / 2;
