function groupAndSort(input) {
  const groups = {};

  // Group items by their "group" property
  for (const item of input) {
    const { group } = item;

    if (!groups[group]) {
      groups[group] = [];
    }

    groups[group].push(item);
  }

  // Sort groups in descending order based on the number of items
  const sortedGroups = Object.entries(groups).sort((a, b) => b[1].length - a[1].length);

  // Sort each group array alphabetically based on the "name" property
  for (const [group, items] of sortedGroups) {
    items.sort((a, b) => a.name.localeCompare(b.name));
  }

  // Filter out groups with less than 3 items
