// Constants
const DEBOUNCE_DELAY = 300; // milliseconds

// DOM elements
const inputField = document.getElementById('autocomplete-input');
const dropdown = document.getElementById('autocomplete-dropdown');

// Debounce mechanism
let debounceTimeout;

// Event listener for input field
inputField.addEventListener('input', function() {
  // Clear existing debounce timeout
  clearTimeout(debounceTimeout);

  // Set new debounce timeout
  debounceTimeout = setTimeout(function() {
    fetchAutocompleteResults(inputField.value);
  }, DEBOUNCE_DELAY);
});

// Fetch autocomplete results
function fetchAutocompleteResults(query) {
  // Clear dropdown
  dropdown.innerHTML = '';

  // If query is empty, return
  if (!query) {
    return;
  }

  // Send API request
  fetch('https://api.example.com/autocomplete?q=' + query)
    .then(response => response.json())
    .then(data => {
      // Check if API request was successful
      if (data && Array.isArray(data)) {
        displayAutocompleteResults(data);
      } else {
        displayError('Unable to fetch autocomplete results');
      }
    })
    .catch(() => {
      displayError('Unable to connect to server');
    });
}

// Display autocomplete results in dropdown
function displayAutocompleteResults(results) {
  // Clear dropdown
  dropdown.innerHTML = '';

  // Create and append list items
  results.forEach(result => {
    const listItem = document.createElement('li');
    listItem.textContent = result;
    dropdown.appendChild(listItem);
  });
}

// Display error message
function displayError(message) {
  dropdown.innerHTML = '<li class="error">' + message + '</li>';
}
