function calculateSquareRoots(arr) {
  const result = [];

  for (let i = 0; i < arr.length; i++) {
    const sqrt = Math.sqrt(arr[i]);
    const roundedSqrt = Math.round(sqrt);
    result.push(roundedSqrt);
  }

  return result;
}
