```javascript
function generateRandomArray(size) {
  // Create the empty 2D array
  const array = [];

  // Generate the random integers for each row
  for (let i = 0; i < size; i++) {
    const row = [];

    // Generate a random integer for each column
    for (let j = 0; j < size; j++) {
      let num;
      // Generate a random number until it is unique within its row and column
      do {
        num = Math.floor(Math.random() * (size * size)) + 1;
      } while (row.includes(num) || array.some(arr => arr[j] === num));

      row.push(num);
    }

    array.push(row);
  }

  return array;
}

// Generate a random 4x4 array
const randomArray = generateRandomArray(4);
console.log(randomArray);
```

To check if the generated array is a magic square, you can use the following function:

```javascript
function isMagicSquare(array) {
  const size = array.length;

  // Calculate the expected sum
  const sum = (size * (size * size + 1)) / 2;

  // Check rows and columns
  for (let i = 0; i < size; i++) {
    let rowSum = 0;
    let colSum = 0;

    for (let j = 0; j < size; j++) {
      rowSum += array[i][j];
      colSum += array[j][i];
    }

    if (rowSum !== sum || colSum !== sum) {
      return false;
    }
  }

  // Check diagonals
  let diagonalSum1 = 0;
  let diagonalSum2 = 0;

  for (let i = 0; i < size; i++) {
    diagonalSum1 += array[i][i];
    diagonalSum2 += array[i][size - i - 1];
  }

  if (diagonalSum1 !== sum || diagonalSum2 !== sum) {
    return false;
  }

  return true;
}

console.log(isMagicSquare(randomArray));
```

This code will generate a random 4x4 array, check if it is a magic square, and print the result. You can change the size parameter in the `generateRandomArray` function to generate arrays of different sizes.

