  for (const key in object) {
    const value = object[key];

    if (typeof value === 'object' && !Array.isArray(value)) {
      if (searchObject(value, keyword)) {
        return true;
      }
    } else if (Array.isArray(value)) {
      if (searchArray(value, keyword)) {
        return true;
      }
    } else {
      if (searchValue(value, keyword)) {
        return true;
      }
    }
  }

  return false;
}

function searchArray(array, keyword) {
  for (let i = 0; i < array.length; i++) {
    const element = array[i];

    if (typeof element === 'object' && !Array.isArray(element)) {
      if (searchObject(element, keyword)) {
        return true;
      }
    } else if (Array.isArray(element)) {
      if (searchArray(element, keyword)) {
        return true;
      }
    } else {
      if (searchValue(element, keyword)) {
        return true;
      }
    }
  }

