function countWords(str) {
  // Convert the string to lowercase and remove punctuation marks
  const cleanedStr = str.toLowerCase().replace(/[^\w\s]/g, '');

  // Define the common stop words
  const stopWords = ["the", "is", "and", "of", "in", "to", "a", "that", "it", "as"];

  // Split the string into an array of words
  const words = cleanedStr.split(" ");

  // Create an object to store the word count
  const wordCount = {};

  // Iterate over each word
  words.forEach(word => {
    // Skip the word if it is a stop word
    if (stopWords.includes(word)) {
      return;
    }

    // Increment the count for the current word
    if (wordCount[word]) {
      wordCount[word]++;
    } else {
      wordCount[word] = 1;
    }
  });

  return wordCount;
