Here is a Node.js command that rotates an array by a given number of positions in place, without using any built-in array methods or extra space:

```javascript
function rotateArray(arr, positions) {
  if (arr.length === 0) {
    return arr;
  }

  const rotateRight = positions > 0;
  const rotateAmount = Math.abs(positions) % arr.length;

  if (rotateAmount === 0) {
    return arr;
  }

  if (rotateRight) {
    for (let i = 0; i < rotateAmount; i++) {
      const last = arr[arr.length - 1];
      for (let j = arr.length - 1; j > 0; j--) {
        arr[j] = arr[j - 1];
      }
      arr[0] = last;
    }
  } else {
    for (let i = 0; i < rotateAmount; i++) {
      const first = arr[0];
      for (let j = 0; j < arr.length - 1; j++) {
        arr[j] = arr[j + 1];
      }
      arr[arr.length - 1] = first;
    }
  }

  return arr;
}

const originalArray = [1, 2, 3, 4, 5];
const positionsToRotate = 2;

console.log("Original array:", originalArray);
console.log("Rotated array:", rotateArray(originalArray, positionsToRotate));
```

