function validateCreditCard(cardNumber, companyCode, isRewardCard) {
  // Step 1: Remove spaces and dashes from the credit card number
  cardNumber = cardNumber.replace(/[\s-]/g, '');

  // Step 2: Convert the credit card number to an array of digits
  let digits = Array.from(cardNumber, Number);

  // Step 3: Reverse the array of digits
  digits.reverse();

  // Step 4: Double every other digit starting from the second-to-last digit
  for (let i = 1; i < digits.length; i += 2) {
    digits[i] *= 2;
    // Step 5: Subtract 9 from any doubled digits greater than 9
    if (digits[i] > 9) {
      digits[i] -= 9;
    }
  }

  // Step 6: Sum all the digits in the modified array
  let sum = digits.reduce((acc, val) => acc + val, 0);

  // Step 7: Check if the sum is divisible by 10
  let isValid = sum % 10 === 0;

  // Step 8: Check if the company code parameter is provided and if the first few digits match the company code
  let belongsToCompany = companyCode ? cardNumber.startsWith(companyCode) : true;

  // Step 9: Check if the reward card flag is provided and if the last digit is 9
  let isReward = isRewardCard ? cardNumber.slice(-1) === '9' : true;

  // Return true if the card is valid, belongs to the specified company, and is a reward card; otherwise return false
  return isValid && belongsToCompany && isReward;
}
