```javascript
function findMostFrequentWord(str) {
  const cleanStr = str.replace(/[^\w\s]|_/g, "").replace(/\s+/g, " ");

  let maxFreq = 0;
  let maxFreqWord = "";
  let minAlphaWord = "";

  let wordStart = -1;
  let wordEnd = -1;
  let currentWord = "";

  for (let i = 0; i < cleanStr.length; i++) {
