    if (char !== " ") {
      // Check if the current character is the start of a new word
      if (wordStart === -1) {
        wordStart = i;
      }

      // Update the current word
      currentWord += char;
    } else {
      // Check if the current character is the end of a word
      if (wordStart !== -1) {
        wordEnd = i;
        const frequency = wordEnd - wordStart;

        // Update the maximum frequency and word accordingly
        if (frequency > maxFreq || (frequency === maxFreq && currentWord < minAlphaWord)) {
          maxFreq = frequency;
          maxFreqWord = currentWord;
          minAlphaWord = currentWord;
        }

        // Reset the variables for the next word
        wordStart = -1;
        currentWord = "";
      }
    }
  }

  return maxFreqWord;
}
