class Playlist {
  constructor() {
    this.songs = [];
  }

  addSong(title, artist, album, genre, duration) {
    if (this.songs.length >= 100) {
      console.log("Playlist is full. Cannot add more songs.");
      return;
    }

    const newSong = {
      title,
      artist,
      album,
      genre,
      duration
    };

    this.songs.push(newSong);
  }

  removeSong(title) {
    const index = this.songs.findIndex(song => song.title === title);

    if (index === -1) {
      console.log("Song not found in the playlist.");
      return;
    }

    this.songs.splice(index, 1);
  }

  getTotalDuration() {
    let totalSeconds = this.songs.reduce(
      (acc, song) => acc + song.duration,
      0
    );

    const hours = Math.floor(totalSeconds / 3600);
    totalSeconds %= 3600;
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;

    return `${hours}:${minutes}:${seconds}`;
  }

  getAverageDuration() {
    const totalSeconds = this.songs.reduce(
      (acc, song) => acc + song.duration,
      0
    );

    const averageSeconds = Math.floor(totalSeconds / this.songs.length);
    const minutes = Math.floor(averageSeconds / 60);
    const seconds = averageSeconds % 60;

    return `${minutes}:${seconds}`;
  }

  getSongByTitle(title) {
    return this.songs.find(song => song.title === title);
  }

  getLongestSong() {
    let longestSong = this.songs[0];

    for (let i = 1; i < this.songs.length; i++) {
      if (this.songs[i].duration > longestSong.duration) {
        longestSong = this.songs[i];
      }
    }

    return longestSong;
  }

  getShortestSong() {
    let shortestSong = this.songs[0];

    for (let i = 1; i < this.songs.length; i++) {
      if (this.songs[i].duration < shortestSong.duration) {
        shortestSong = this.songs[i];
      }
    }

    return shortestSong;
  }

  shuffle() {
    const shuffledSongs = [];

    const artists = Array.from(new Set(this.songs.map(song => song.artist)));
    const artistCount = artists.length;

    if (artistCount < 2) {
      console.log(
        "Not enough songs by different artists to ensure no consecutive songs by the same artist."
      );
      return;
    }

    let prevArtistIndex = -1;
    let currentArtistIndex = Math.floor(Math.random() * artistCount);

    while (this.songs.length > 0) {
      const songsByCurrentArtist = this.songs.filter(
        song => song.artist === artists[currentArtistIndex]
      );

      if (songsByCurrentArtist.length === 0) {
        artists.splice(currentArtistIndex, 1);
        artistCount--;
        if (artistCount < 2) {
          console.log(
            "Not enough songs by different artists to ensure no consecutive songs by the same artist."
          );
          return;
        }
        continue;
      }

      const randomSongIndex = Math.floor(
        Math.random() * songsByCurrentArtist.length
      );
      const randomSong = songsByCurrentArtist[randomSongIndex];

      shuffledSongs.push(randomSong);
      this.songs.splice(
        this.songs.findIndex(song => song === randomSong),
        1
      );

      prevArtistIndex = currentArtistIndex;
      currentArtistIndex = Math.floor(Math.random() * artistCount);
      if (currentArtistIndex === prevArtistIndex) {
        currentArtistIndex =
          currentArtistIndex === artistCount - 1 ? 0 : currentArtistIndex + 1;
      }
    }

    this.songs = shuffledSongs;
  }
}
