function getElements(className, parentID) {
  const parentElement = document.getElementById(parentID);
  if (!parentElement) {
    return [];
  }

  const elements = Array.from(parentElement.getElementsByClassName(className));

  const filteredElements = elements.filter((element) => {
    const ignoreAttribute = element.getAttribute('data-ignore');
    const siblingElement = element.nextElementSibling;
    const hasSiblingClass = siblingElement && siblingElement.classList.contains('siblingClass');
    return ignoreAttribute !== 'true' && !hasSiblingClass;
  });

  filteredElements.sort((a, b) => {
    const aText = a.textContent.trim();
    const bText = b.textContent.trim();
    return bText.localeCompare(aText);
  });

  return filteredElements;
}
