Here is a function that takes a paragraph as input, removes stop words, and returns the number of distinct words in the paragraph:

```javascript
function countDistinctWords(paragraph) {
  const stopWords = ['a', 'an', 'the', 'and', 'or', 'etc.']; // list of stop words

  // Remove punctuation marks and convert to lowercase
  const normalizedParagraph = paragraph.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, '').toLowerCase();

  // Split paragraph into words
  const words = normalizedParagraph.split(' ');

  // Remove stop words
  const filteredWords = words.filter(word => !stopWords.includes(word));

  // Create a set of distinct words
  const distinctWords = new Set(filteredWords);

  // Return the count of distinct words
  return distinctWords.size;
}
```

