Here is the JavaScript class that generates random numbers and keeps track of their frequency:

```javascript
class RandomNumberGenerator {
  constructor() {
    this.generatedNumbers = {};
  }

  generateRandomNumber() {
    const randomNumber = Math.floor(Math.random() * 100) + 1;

    if (randomNumber in this.generatedNumbers) {
      this.generatedNumbers[randomNumber]++;
    } else {
      this.generatedNumbers[randomNumber] = 1;
    }
  }

  getGeneratedNumbers() {
    return this.generatedNumbers;
  }

  getMostFrequentNumber() {
    let mostFrequentNumber = null;
    let maxFrequency = 0;

    for (const number in this.generatedNumbers) {
      if (this.generatedNumbers[number] > maxFrequency) {
        mostFrequentNumber = parseInt(number);
        maxFrequency = this.generatedNumbers[number];
      }
    }

    return mostFrequentNumber;
  }

  getLeastFrequentNumber() {
    let leastFrequentNumber = null;
    let minFrequency = Infinity;

    for (const number in this.generatedNumbers) {
      if (this.generatedNumbers[number] < minFrequency) {
        leastFrequentNumber = parseInt(number);
        minFrequency = this.generatedNumbers[number];
      }
    }

    return leastFrequentNumber;
  }

  getNumbersInAscendingOrder() {
    const numbers = Object.keys(this.generatedNumbers).map(Number);
    const sortedNumbers = [];

    for (let i = 1; i <= 100; i++) {
      if (numbers.includes(i)) {
        sortedNumbers.push(i);
      }
    }

    return sortedNumbers;
  }

  getNumbersInDescendingOrder() {
    return this.getNumbersInAscendingOrder().reverse();
  }

  getTotalGeneratedNumbers() {
    let totalGenerated = 0;

    for (const number in this.generatedNumbers) {
      totalGenerated += this.generatedNumbers[number];
    }

    return totalGenerated;
  }

  getUniqueGeneratedNumbers() {
    return Object.keys(this.generatedNumbers).length;
  }

  reset() {
    this.generatedNumbers = {};
  }
}
```

