  for (var i = 0; i < elements.length; i++) {
    var element = elements[i];

    // Check if the element is not a child of another specific element
    if (!element.parentElement.classList.contains('parent-class')) {

      // Check if the element has at least one sibling element with a specific attribute value
      var siblings = element.parentElement.children;
      var hasSpecificAttributeSibling = false;

      for (var j = 0; j < siblings.length; j++) {
        var sibling = siblings[j];

        if (sibling !== element && sibling.hasAttribute('specific-attribute')) {
          hasSpecificAttributeSibling = true;
          break;
        }
      }

      // Hide the element if it meets all the conditions
      if (hasSpecificAttributeSibling) {
        element.style.display = 'none';
      }
    }
  }
}

// Call the function
hideElement();
