Here's a JavaScript function that takes in an array of numbers and returns two arrays: one containing all the prime numbers and one containing all the composite numbers. The function uses a recursive approach to determine whether a number is prime or composite, and does not use any built-in JavaScript methods or libraries to check for prime numbers or sort the arrays:

```javascript
function isPrime(n, divisor = 2) {
  if (n <= 2) {
    return n === 2;
  }
  if (n % divisor === 0) {
    return false;
  }
  if (divisor * divisor > n) {
    return true;
  }
  return isPrime(n, divisor + 1);
}

function separateNumbers(arr) {
  const primes = [];
  const composites = [];

  for (let i = 0; i < arr.length; i++) {
    const num = arr[i];
    if (isPrime(num)) {
      primes.push(num);
    } else {
      composites.push(num);
    }
  }

  primes.sort((a, b) => a - b);
  composites.sort((a, b) => b - a);

  return [primes, composites];
}
```

To use this function, you can call `separateNumbers` with an array of numbers as the argument. For example:

