Here's a JavaScript program that counts the occurrences of each element in an array and returns the elements in descending order based on their occurrence count. If there are elements with the same occurrence count, it sorts them alphabetically. The program has a time complexity of O(n log n).

```javascript
function countOccurrences(arr) {
  // Create an object to store the count of each element
  const count = {};

  // Iterate through the array and count the occurrences of each element
  arr.forEach((elem) => {
    if (count[elem]) {
      count[elem]++;
    } else {
      count[elem] = 1;
    }
  });

  // Convert the object into an array of [element, count] pairs
  const pairs = Object.entries(count);

  // Sort the array of pairs in descending order based on the count
  // If the counts are equal, sort alphabetically
  pairs.sort((a, b) => {
    if (b[1] === a[1]) {
      return a[0].localeCompare(b[0]);
    } else {
      return b[1] - a[1];
    }
  });

  // Extract the elements from the sorted array of pairs
  const sortedElements = pairs.map((pair) => pair[0]);

  return sortedElements;
}

