      throw new Error('Input must be less than or equal to 50');
    }

    const fibonacciArray = [0, 1];
    let prevNum = 0;
    let currNum = 1;

    for (let i = 3; i <= num; i++) {
      const nextNum = prevNum + currNum;
      fibonacciArray.push(nextNum);
      prevNum = currNum;
      currNum = nextNum;
    }

    return fibonacciArray;
  }
}

