        return;

    // Find the last node in the linked list
    struct node *lastNode = node;
    while(lastNode->next != node)
    {
        lastNode = lastNode->next;
    }

    // Traverse the linked list to find the node to delete
    struct node *currentNode = node;
    while(currentNode != NULL && currentNode != node)
    {
        currentNode = currentNode->next;
    }

    // Swap the data of the node to delete with the data of the last node
    int tempData = node->data;
    node->data = lastNode->data;
    lastNode->data = tempData;

    // Remove the last node from the linked list
    struct node *prevNode = node;
    while(prevNode->next != lastNode)
    {
        prevNode = prevNode->next;
    }
    prevNode->next = node;
}

