function removeDuplicates(arr) {
  // Create an object to keep track of the unique elements
  const uniqueElements = {};

  // Iterate over the array
  for (let i = 0; i < arr.length; i++) {
    const num = arr[i];

    // If the current element is not in the object, add it
    if (!uniqueElements[num]) {
      uniqueElements[num] = true;
    } else {
      // If the current element is already in the object, remove it from the array
      arr.splice(i, 1);
      // Since we removed an element, we need to decrement the index to continue with the next element
      i--;
    }
  }

  // Return the modified array
  return arr;
}

