- The `sumOfPrimes` function calculates the sum of the first n prime numbers by iterating from 2 until it finds n prime numbers. It checks each number using the `isPrime` function and adds it to the sum if it is prime. It also keeps track of the count to ensure that it stops when it finds n prime numbers.

```javascript
// Function to check if a number is prime using the Sieve of Eratosthenes
function isPrime(num) {
  if (num < 2) {
    return false;
  }
  let primes = new Array(num + 1).fill(true);
  primes[0] = false;
  primes[1] = false;

  for (let i = 2; i <= Math.sqrt(num); i++) {
    if (primes[i]) {
      for (let j = i ** 2; j <= num; j += i) {
        primes[j] = false;
      }
    }
  }
  return primes[num];
}

