```javascript
function getFrequencyArray(arr) {
  // Function to flatten the nested arrays
  const flatten = (array) => {
    return array.reduce((acc, val) => Array.isArray(val) ? acc.concat(flatten(val)) : acc.concat(val), []);
  }

  // Function to get the string representation of an object
  const getObjectString = (obj) => {
    return JSON.stringify(obj);
  }

  // Count the frequency of each element in the input array
  const frequencyMap = new Map();
  const flattenArr = flatten(arr);
  flattenArr.forEach((element) => {
    const key = typeof element === 'object' ? getObjectString(element) : element.toString();
    frequencyMap.set(key, (frequencyMap.get(key) || 0) + 1);
  });

  // Convert the map to an array of objects
  const frequencyArray = Array.from(frequencyMap).map(([element, frequency]) => {
    return { element, frequency };
  });

  // Sort the objects based on the frequency in descending order
  frequencyArray.sort((a, b) => {
    if (a.frequency !== b.frequency) {
      return b.frequency - a.frequency;
    } else {
      return a.element.localeCompare(b.element);
    }
  });

  return frequencyArray;
}

