```javascript
function findLongestWords(str) {
  // Remove punctuation marks and special characters
  const cleanedStr = str.replace(/[^\w\s]|_/g, "").replace(/\s+/g, " ");

  let longestWordLength = 0;
  let longestWords = [];

  let currentWord = "";
  for (let i = 0; i < cleanedStr.length; i++) {
    const char = cleanedStr[i];

    // If the current character is a letter, add it to the current word
    if (/[a-zA-Z]/.test(char)) {
      currentWord += char;
    } else if (currentWord) {
      // If the current word has ended, check if it is the longest word so far
      if (currentWord.length > longestWordLength) {
        longestWordLength = currentWord.length;
        longestWords = [currentWord];
      } else if (currentWord.length === longestWordLength) {
        longestWords.push(currentWord);
      }
      currentWord = "";
    }
  }

  return longestWords;
}
```

