import { Component, OnInit } from '@angular/core';
import { Country } from './country.model';
import { CountryService } from './country.service';

@Component({
  selector: 'app-dropdown',
  templateUrl: './dropdown.component.html',
  styleUrls: ['./dropdown.component.css']
})
export class DropdownComponent implements OnInit {
  countries: Country[] = [];
  filteredCountries: Country[] = [];
  selectedCountries: Country[] = [];
  searchTerm: string = '';

  constructor(private countryService: CountryService) {}

  ngOnInit() {
    this.countryService.getCountries().subscribe((countries) => {
      this.countries = countries;
      this.filteredCountries = countries;
    });
  }

  filterCountries() {
    this.filteredCountries = this.countries.filter((country) =>
      country.name.toLowerCase().includes(this.searchTerm.toLowerCase())
    );
  }

  addCountry(country: Country) {
    country.selected = true;
    this.selectedCountries.push(country);
  }

  removeCountry(country: Country) {
    country.selected = false;
    this.selectedCountries = this.selectedCountries.filter((c) => c !== country);
  }

  onDragStart(event: DragEvent, country: Country) {
    event.dataTransfer?.setData('text/plain', JSON.stringify(country));
  }

  onDragOver(event: DragEvent) {
    event.preventDefault();
  }

  onDrop(event: DragEvent, country: Country) {
    event.preventDefault();
    const draggedCountry = JSON.parse(event.dataTransfer?.getData('text/plain') || '');
    const draggedIndex = this.selectedCountries.indexOf(draggedCountry);
    const droppedIndex = this.selectedCountries.indexOf(country);

    if (draggedIndex > -1 && droppedIndex > -1) {
      this.selectedCountries.splice(draggedIndex, 1);
      this.selectedCountries.splice(droppedIndex, 0, draggedCountry);
    }
  }
}
