function calculateSums(numbers) {
  let positiveSum = 0;
  let negativeSum = 0;
  let zeroSum = 0;

  const uniquePositiveNumbers = new Set();

  for (let i = 0; i < numbers.length; i++) {
    const number = numbers[i];

    if (number > 0) {
      uniquePositiveNumbers.add(number);
    } else if (number < 0) {
      negativeSum += Math.pow(number, 2);
    } else {
      zeroSum += Math.pow(number, 2);
    }
  }

  for (let positiveNumber of uniquePositiveNumbers) {
    positiveSum += Math.pow(positiveNumber, 2);
  }

  return {
    positiveSum,
    negativeSum,
    zeroSum
  };
}

