// Function to calculate the median temperature
function calculateMedianTemperature(temperatures) {
  // Filter out temperatures below 0 degrees Celsius
  const filteredTemperatures = temperatures.filter(temp => temp >= 0);

  // Sort the filtered temperatures in ascending order
  const sortedTemperatures = filteredTemperatures.sort((a, b) => a - b);

  // Calculate the middle index of the sorted temperatures array
  const middleIndex = Math.floor(sortedTemperatures.length / 2);

  // Check if the number of temperatures is odd
  if (sortedTemperatures.length % 2 === 1) {
    // Return the middle value
    return Math.round(sortedTemperatures[middleIndex]);
  } else {
    // Calculate the average of the two middle values
    const middleValuesAverage = Math.round(
      (sortedTemperatures[middleIndex - 1] + sortedTemperatures[middleIndex]) / 2
    );
    return middleValuesAverage;
  }
}

