To find the nth Fibonacci number without using loops or recursion and with a time complexity of O(log n), we can use matrix exponentiation.

The Fibonacci sequence can be represented using a matrix equation:

```
| Fn   |   | 1 1 |   | Fn-1 |
|      | = |     | * |      |
| Fn-1 |   | 1 0 |   | Fn-2 |
```

To find the nth Fibonacci number, we need to calculate the (n-1)th power of the matrix:

```
| Fn   |   | 1 1 |^(n-1)   | F1 |
|      | = |     |      *  |    |
| Fn-1 |   | 1 0 |         | F0 |
```

Here's the JavaScript code to implement this approach:

```javascript
function fibonacci(n) {
  if (n <= 0) {
    return 0;
  }

  const matrix = [[1, 1], [1, 0]];
  const result = matrixPower(matrix, n - 1);

  return result[0][0];
}

function matrixMultiply(matrix1, matrix2) {
  const rows1 = matrix1.length;
  const cols1 = matrix1[0].length;
  const cols2 = matrix2[0].length;

  const result = [];
  for (let i = 0; i < rows1; i++) {
    result.push([]);
    for (let j = 0; j < cols2; j++) {
      let sum = 0;
      for (let k = 0; k < cols1; k++) {
        sum += matrix1[i][k] * matrix2[k][j];
      }
      result[i].push(sum);
    }
  }

  return result;
}

function matrixPower(matrix, n) {
  if (n <= 1) {
    return matrix;
  }

  const half = matrixPower(matrix, Math.floor(n / 2));
  const result = matrixMultiply(half, half);

  if (n % 2 === 1) {
    return matrixMultiply(result, matrix);
  } else {
    return result;
  }
}

// Example usage:
console.log(fibonacci(5)); // Output: 5
console.log(fibonacci(10)); // Output: 55
console.log(fibonacci(15)); // Output: 610
