function sumOfFirstNPrimes(n) {
  if (!Number.isInteger(n) || n <= 0) {
    return "Input must be a positive integer.";
  }

  if (n < 1 || n > 1000) {
    return "Input must be within the range of 1 to 1000.";
  }

  let primes = [];
  let num = 2;
  while (primes.length < n) {
    let isPrime = true;
    for (let i = 2; i <= Math.sqrt(num); i++) {
      if (num % i === 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime) {
      primes.push(num);
    }
    num++;
  }

  let sum = primes.reduce((acc, curr) => acc + curr, 0);
  return sum;
}
