function sumOfPairs(arr, target) {
  let sum = 0;
  let seen = new Set();

  for (let i = 0; i < arr.length; i++) {
    let complement = target - arr[i];

    if (seen.has(complement)) {
      sum += complement;
    }

    seen.add(arr[i]);
  }

  return sum;
}
