Here's a recursive JavaScript program that sorts an array of strings according to the given requirements:

```javascript
function sortStrings(arr) {
  // Remove duplicate strings from the array
  arr = [...new Set(arr)];

  // Filter out strings containing numbers or special characters
  arr = arr.filter(str => /^[a-zA-Z]+$/.test(str));

  // Recursive sort function
  function recursiveSort(arr) {
    if (arr.length <= 1) {
      return arr;
    }

    const pivot = arr[0];
    const smaller = [];
    const equal = [];
    const larger = [];

    for (let str of arr) {
      if (str.length < pivot.length) {
        smaller.push(str);
      } else if (str.length === pivot.length) {
        equal.push(str);
      } else {
        larger.push(str);
      }
    }

    return recursiveSort(larger).concat(equal, recursiveSort(smaller));
  }

  return recursiveSort(arr);
}

// Example usage:
const arr = ["Hello", "world", "JavaScript", "sort", "this", "array", "by", "string", "length", "JAVASCRIPT"];
console.log(sortStrings(arr));
```

