function getObjectAbsoluteDifference(obj1, obj2) {
  const visited1 = new Set();
  const visited2 = new Set();

  function getNumericProperties(obj, visited) {
    const numericProperties = [];
    for (let key in obj) {
      if (!visited.has(obj[key])) {
        visited.add(obj[key]);
        if (typeof obj[key] === 'number') {
          numericProperties.push(obj[key]);
        } else if (typeof obj[key] === 'object' && obj[key] !== null) {
          numericProperties.push(...getNumericProperties(obj[key], visited));
        }
      }
    }
    return numericProperties;
  }

  const numericProperties1 = getNumericProperties(obj1, visited1);
  const numericProperties2 = getNumericProperties(obj2, visited2);

  let sum1 = 0;
  for (let num of numericProperties1) {
    sum1 += num;
  }

  let sum2 = 0;
  for (let num of numericProperties2) {
    sum2 += num;
  }

  return Math.abs(sum1 - sum2);
}
```

This solution uses a recursive approach to traverse the objects and extract all the numeric properties. It keeps track of visited objects to handle circular references and ensures that no properties are accessed more than once.

The time complexity of this solution is O(n), where n is the total number of numeric properties in the objects. This is because we only visit each numeric property once, regardless of the depth of the object.

