    # Increase font size of paragraphs
    for p in soup.find_all('p'):
        if not is_excluded(p, excluded_elements, excluded_classes):
            p['style'] = get_new_font_size(p.get('style'))

    return str(soup)


def is_excluded(element, excluded_elements, excluded_classes):
    if excluded_elements and element.name in excluded_elements:
        return True

    if excluded_classes and element.get('class'):
        for class_ in element.get('class'):
            if class_ in excluded_classes:
                return True

    return False


def get_new_font_size(style):
    if style:
        properties = style.split(';')

        for i, property_ in enumerate(properties):
            property_ = property_.strip()

            if property_.startswith('font-size'):
                key, value = property_.split(':')
                value = value.strip()

                if value.endswith('px'):
                    new_value = int(value[:-2]) * 2
                    properties[i] = f'{key}: {new_value}px'
                elif value.endswith('pt'):
                    # Convert points to pixels
                    new_value = int(value[:-2]) * (96 / 72) * 2
                    properties[i] = f'{key}: {new_value}px'
                elif value.endswith('%'):
                    # Convert percentage to pixels
                    parent_element = get_parent_element(property_)
                    parent_font_size = get_font_size(parent_element.get('style'))
                    new_value = parent_font_size * int(value[:-1]) / 100
                    properties[i] = f'{key}: {new_value}px'

        return '; '.join(properties)

    return 'font-size: 24px'


def get_parent_element(style):
