Here's an implementation in JavaScript to construct an array of 1000 random numbers between -1000 and 1000, without using any built-in JavaScript functions for generating random numbers. The array will not have any duplicates and will be sorted in descending order:

```javascript
// Function to generate a random number between min and max (inclusive)
function getRandomNumber(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

// Function to check if a number already exists in the array
function isDuplicate(arr, num) {
  return arr.includes(num);
}

// Generate an array of 1000 random numbers
function generateRandomArray() {
  let arr = [];

  while (arr.length < 1000) {
    let num = getRandomNumber(-1000, 1000);

    if (!isDuplicate(arr, num)) {
      arr.push(num);
    }
  }

  return arr.sort((a, b) => b - a);
}

// Generate and print the array
console.log(generateRandomArray());
```

