```javascript
function isPrime(num) {
  if (num <= 1) {
    return false;
  }

  for (let i = 2; i <= Math.sqrt(num); i++) {
    if (num % i === 0) {
      return false;
    }
  }

  return true;
}

function sumOfPrimes(values) {
  let sum = 0;

  for (let i = 0; i < values.length; i++) {
    const num = parseFloat(values[i]);

    if (!isNaN(num) && isPrime(num)) {
      sum += num;
    }
  }

  return Math.round(sum);
}

const values = [1, 2.5, -3, 4, 5, 'abc', true, null, undefined, NaN, Infinity, -2.7, 3.2];
const sum = sumOfPrimes(values);

console.log(sum);
```

