Write a JavaScript function that takes in a string representing a paragraph and returns an object containing the most common words in the paragraph, excluding common stop words. The function should also exclude any words that are less than 4 characters long. The function should return the words along with their frequency in descending order.

Reference code:
```
function getMostCommonWords(paragraph) {
  var words = paragraph.split(' ');
  var wordCount = {};

  for (var i = 0; i < words.length; i++) {
    var word = words[i];
    if (word.length < 4) {
      continue;
    }
    if (wordCount[word]) {
      wordCount[word]++;
    } else {
      wordCount[word] = 1;
    }
  }

  var sortedWords = Object.keys(wordCount).sort(function(a, b) {
    return wordCount[b] - wordCount[a];
  });

  return sortedWords.map(function(word) {
    return { word: word, frequency: wordCount[word] };
  });
}
```

