function fibonacciRecursive(n) {
  if (n <= 1) {
    return n;
  }
  return fibonacciRecursive(n - 1) + fibonacciRecursive(n - 2);
}

function generateFibonacciSequence(n) {
  let sequence = [];
  for (let i = n; i >= 0; i--) {
    sequence.push(fibonacciRecursive(i));
  }
  return sequence;
}

function reverseFibonacciSequence(sequence) {
  return sequence.reverse();
}

function calculateSum(sequence) {
  let sum = 0;
  for (let i = 0; i < sequence.length; i++) {
    sum += sequence[i];
  }
  return sum;
}

function runProgram() {
  const number = parseInt(prompt("Enter a number:"));

  if (isNaN(number) || number <= 0) {
    console.log("Invalid input. Please enter a positive number.");
    return;
  }

  const sequence = generateFibonacciSequence(number);
  const reversedSequence = reverseFibonacciSequence(sequence);
  const sum = calculateSum(sequence);

  console.log("Fibonacci sequence in reverse order: " + reversedSequence.join(", "));
  console.log("Sum of Fibonacci numbers: " + sum);
}

