function generateFibonacciSequence(limit) {
  if (typeof limit !== 'number' || !Number.isInteger(limit) || limit <= 0) {
    throw new Error('Input argument must be a positive integer');
  }

  let fibonacciSequence = [0, 1];
  let sum = 1;

  while (fibonacciSequence[fibonacciSequence.length - 1] < limit) {
    const nextNumber = fibonacciSequence[fibonacciSequence.length - 1] + fibonacciSequence[fibonacciSequence.length - 2];
    fibonacciSequence.push(nextNumber);
    sum += nextNumber;
  }

  return { sequence: fibonacciSequence, sum };
}
