Here is the implementation of the bubble sort algorithm to sort an array of objects based on the given criteria:

```javascript
function bubbleSort(arr) {
  const n = arr.length;

  for (let i = 0; i < n - 1; i++) {
    for (let j = 0; j < n - i - 1; j++) {
      if (arr[j].score < arr[j + 1].score) {
        swap(arr, j, j + 1);
      } else if (arr[j].score === arr[j + 1].score) {
        if (arr[j].age > arr[j + 1].age) {
          swap(arr, j, j + 1);
        } else if (arr[j].age === arr[j + 1].age) {
          if (arr[j].name.toLowerCase() > arr[j + 1].name.toLowerCase()) {
            swap(arr, j, j + 1);
          } else if (arr[j].name.toLowerCase() === arr[j + 1].name.toLowerCase()) {
            if (arr[j].gender.toLowerCase() > arr[j + 1].gender.toLowerCase()) {
              swap(arr, j, j + 1);
            }
          }
        }
      }
    }
  }

  return arr;
}

function swap(arr, i, j) {
  const temp = arr[i];
  arr[i] = arr[j];
  arr[j] = temp;
}

// Example usage
const arr = [
  {name: "John", age: 25, score: 85, gender: "male"},
  {name: "Jane", age: 30, score: 90, gender: "female"},
  {name: "Tom", age: 25, score: 85, gender: "male"},
  {name: "Alice", age: 35, score: 80, gender: "female"},
  {name: "Bob", age: 30, score: 90, gender: "male"},
  {name: "Eve", age: 25, score: 80, gender: "female"}
];

const sortedArr = bubbleSort(arr);
console.log(sortedArr);
```

This implementation uses nested loops to iterate through the array and compares adjacent objects based on the given criteria. The `swap` function is used to swap the positions of two objects in the array if they need to be rearranged. The `bubbleSort` function returns the sorted array.

