    if ((isNumber(a) && isSpecialChar(b)) || (isSpecialChar(a) && isNumber(b))) {
      return isNumber(a) ? -1 : 1;
    }

    // Case 4: Both elements are strings
    return a.localeCompare(b);
  }

  // Sort the array using the custom sorting function
  arr.sort(customSort);

  return arr;
}
