class SearchEngine {
  constructor() {
    this.index = [];
  }

  // Function to add documents to the index
  addDocument(document) {
    this.index.push(document);
  }

  // Function to perform a search operation
  search(query) {
    let low = 0;
    let high = this.index.length - 1;

    while (low <= high) {
      let mid = Math.floor((low + high) / 2);

      if (this.index[mid] === query) {
        return this.index[mid];
      } else if (this.index[mid] < query) {
