  return (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0);
}

// Get the number of days in a month
function getDaysInMonth(month, year) {
  const daysInMonth = [31, isLeapYear(year) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return daysInMonth[month - 1];
}

// Get the index of the start day of the month
function getStartDayIndex(startDay) {
  return daysOfWeek.indexOf(startDay);
}

// Generate the calendar for the given month and year
function generateCalendar(month, year, startDay) {
  const numDays = getDaysInMonth(month, year);
  const startDayIndex = getStartDayIndex(startDay);

  let calendar = [];

  // Fill in the days before the start day
  for (let i = 0; i < startDayIndex; i++) {
    calendar.push('');
  }

  // Fill in the days of the month
  for (let day = 1; day <= numDays; day++) {
    calendar.push(day);
  }

  return calendar;
}

// Generate the calendar for the given month and year
