import java.util.ArrayList;
import java.util.Random;

ArrayList<Circle> circles;
int successfulGenerations = 0;
int failedAttempts = 0;
boolean resetCanvas = false;
Button resetButton;
Counter counter;

void setup() {
  size(600, 600);

  resetButton = new Button(10, height - 40, 80, 30, "Reset");
  counter = new Counter(width - 100, height - 40, successfulGenerations);

  resetCanvas();
}

void draw() {
  background(255);

  if (resetCanvas) {
    resetCanvas();
    resetCanvas = false;
  }

  for (Circle circle : circles) {
    circle.display();
  }

  resetButton.display();
  counter.display();
}

void mousePressed() {
  if (resetButton.isClicked()) {
    resetCanvas = true;
    successfulGenerations = 0;
    failedAttempts = 0;
  } else {
    for (int i = circles.size() - 1; i >= 0; i--) {
      if (circles.get(i).isClicked()) {
        Circle circle = circles.remove(i);
        successfulGenerations--;
        counter.update(successfulGenerations);
        break;
      }
    }
  }
}

void resetCanvas() {
  circles = new ArrayList<Circle>();
  successfulGenerations = 0;
  failedAttempts = 0;
  counter.update(successfulGenerations);

  Random random = new Random();

  while (circles.size() < 1000) {
    int radius = random.nextInt(41) + 10;
    int x = random.nextInt(width - 2 * radius) + radius;
    int y = random.nextInt(height - 2 * radius) + radius;

    Circle circle = new Circle(x, y, radius);

    if (!circle.overlapsWithEdges() && !circle.overlapsWithOtherCircles()) {
      circles.add(circle);
      successfulGenerations++;
      counter.update(successfulGenerations);
    } else {
      failedAttempts++;
    }
  }
}

class Circle {
  int x, y;
  int radius;
  color circleColor;

  Circle(int x, int y, int radius) {
    this.x = x;
    this.y = y;
    this.radius = radius;
    this.circleColor = generateUniqueColor();
  }

  void display() {
    stroke(0);
    fill(circleColor);
    ellipse(x, y, radius * 2, radius * 2);
  }

  boolean overlapsWithEdges() {
    return x - radius < 0 || x + radius > width || y - radius < 0 || y + radius > height;
  }

  boolean overlapsWithOtherCircles() {
    for (Circle circle : circles) {
      if (circle != this) {
        float distance = dist(x, y, circle.x, circle.y);
        if (distance < radius + circle.radius) {
          return true;
        }
      }
    }
    return false;
  }

  boolean isClicked() {
    float distance = dist(x, y, mouseX, mouseY);
    return distance < radius;
  }

  color generateUniqueColor() {
    Random random = new Random();

    while (true) {
      color color = color(random.nextInt(256), random.nextInt(256), random.nextInt(256));

      boolean uniqueColor = true;
      for (Circle circle : circles) {
        if (circle != this && circle.circleColor == color) {
          uniqueColor = false;
          break;
        }
      }

      if (uniqueColor) {
        return color;
      }
    }
  }
}

class Button {
  int x, y;
  int width, height;
  String label;

  Button(int x, int y, int width, int height, String label) {
    this.x = x;
    this.y = y;
    this.width = width;
    this.height = height;
    this.label = label;
  }

