    stroke(0);
    fill(200);
    rect(x, y, width, height);

    fill(0);
    textSize(14);
    textAlign(CENTER, CENTER);
    text(label, x + width/2, y + height/2);
  }

  boolean isClicked() {
    return mouseX > x && mouseX < x + width && mouseY > y && mouseY < y + height;
  }
}

class Counter {
  int x, y;
  int count;

  Counter(int x, int y, int count) {
    this.x = x;
    this.y = y;
    this.count = count;
  }

  void display() {
    fill(0);
    textSize(14);
    textAlign(RIGHT, CENTER);
    text("Successful Generations: " + count, x, y);
  }

  void update(int count) {
    this.count = count;
  }
}
