import React, { useState, useMemo } from 'react';

const TableComponent = ({ data }) => {
  const [filters, setFilters] = useState({});
  const [sortConfig, setSortConfig] = useState({ key: 'id', direction: 'asc' });
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 5;

  // Apply filters to the data
  const filteredData = useMemo(() => {
    return data.filter(item => {
      return Object.keys(filters).every(key => {
        return item[key].toString().toLowerCase().includes(filters[key].toLowerCase());
      });
    });
  }, [data, filters]);

  // Sort the filtered data
  const sortedData = useMemo(() => {
    const { key, direction } = sortConfig;
    return [...filteredData].sort((a, b) => {
      if (a[key] < b[key]) return direction === 'asc' ? -1 : 1;
      if (a[key] > b[key]) return direction === 'asc' ? 1 : -1;
      return 0;
    });
  }, [filteredData, sortConfig]);

  // Calculate pagination
  const totalPages = Math.ceil(sortedData.length / itemsPerPage);
  const indexOfLastItem = currentPage * itemsPerPage;
  const indexOfFirstItem = indexOfLastItem - itemsPerPage;
  const currentItems = sortedData.slice(indexOfFirstItem, indexOfLastItem);

  // Handle filter change
  const handleFilterChange = (e, key) => {
    setFilters({ ...filters, [key]: e.target.value });
  };

  // Handle sort click
  const handleSortClick = (key) => {
    if (sortConfig.key === key) {
      setSortConfig({ ...sortConfig, direction: sortConfig.direction === 'asc' ? 'desc' : 'asc' });
    } else {
      setSortConfig({ key, direction: 'asc' });
    }
  };

  // Handle pagination click
  const handlePaginationClick = (pageNumber) => {
    setCurrentPage(pageNumber);
  };

  // Handle search change
  const handleSearchChange = (e) => {
    const searchTerm = e.target.value.toLowerCase();
    setFilters({ ...filters, search: searchTerm });
  };

  // Handle export click
  const handleExportClick = () => {
    const csvContent = `data:text/csv;charset=utf-8,${sortedData
      .map(item => Object.values(item).join(','))
      .join('\n')}`;
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    link.setAttribute('download', 'table_data.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div>
      <input type="text" placeholder="Search" onChange={handleSearchChange} />

      <table>
        <thead>
          <tr>
            <th>
              ID
              <input type="text" placeholder="Filter" onChange={(e) => handleFilterChange(e, 'id')} />
              <button onClick={() => handleSortClick('id')}>{sortConfig.key === 'id' ? (sortConfig.direction === 'asc' ? '▲' : '▼') : ''}</button>
            </th>
            <th>
              Name
              <input type="text" placeholder="Filter" onChange={(e) => handleFilterChange(e, 'name')} />
              <button onClick={() => handleSortClick('name')}>{sortConfig.key === 'name' ? (sortConfig.direction === 'asc' ? '▲' : '▼') : ''}</button>
            </th>
            <th>
              Age
              <input type="text" placeholder="Filter" onChange={(e) => handleFilterChange(e, 'age')} />
              <button onClick={() => handleSortClick('age')}>{sortConfig.key === 'age' ? (sortConfig.direction === 'asc' ? '▲' : '▼') : ''}</button>
            </th>
            <th>
              Salary
              <input type="text" placeholder="Filter" onChange={(e) => handleFilterChange(e, 'salary')} />
              <button onClick={() => handleSortClick('salary')}>{sortConfig.key === 'salary' ? (sortConfig.direction === 'asc' ? '▲' : '▼') : ''}</button>
            </th>
          </tr>
        </thead>
        <tbody>
          {currentItems.map(item => (
            <tr key={item.id}>
              <td>{item.id}</td>
              <td>{item.name}</td>
              <td>{item.age}</td>
              <td>{item.salary}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <div>
        <button onClick={() => handlePaginationClick(currentPage - 1)} disabled={currentPage === 1}>Previous</button>
        <span>{currentPage} / {totalPages}</span>
