    { name: "February", days: 28 },
    { name: "March", days: 31 },
    { name: "April", days: 30 },
    { name: "May", days: 31 },
    { name: "June", days: 30 },
    { name: "July", days: 31 },
    { name: "August", days: 31 },
    { name: "September", days: 30 },
    { name: "October", days: 31 },
    { name: "November", days: 30 },
    { name: "December", days: 31 },
  ];

  // Extract year, month, and day from the input date
  const [year, month, day] = inputDate.split("-").map(Number);

  // Validate the input date
  if (year < 2000 || year > 2099 || isNaN(month) || month < 1 || month > 12 || isNaN(day) || day < 1 || day > 31) {
    return "Invalid input date";
  }

  // Check for leap year and update February days
  if (year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0)) {
    months[1].days = 29;
  }

  // Calculate the total number of days from 2000-01-01 to the input date
  let totalDays = 0;
  for (let i = 2000; i < year; i++) {
    if (i % 4 === 0 && (i % 100 !== 0 || i % 400 === 0)) {
      totalDays += 366; // leap year
    } else {
      totalDays += 365; // non-leap year
    }
  }
  for (let i = 0; i < month - 1; i++) {
    totalDays += months[i].days;
  }
  totalDays += day - 1;

  // Calculate the day of the week (0 - Sunday, 1 - Monday, ..., 6 - Saturday)
  const daysOfWeek = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
  const dayOfWeek = daysOfWeek[totalDays % 7];

  // Get the current time in DD/MM/YYYY hh:mm:ss format
  const now = new Date();
  const time = `${now.getDate().toString().padStart(2, "0")}/${(now.getMonth() + 1).toString().padStart(2, "0")}/${now.getFullYear()} ${now.getHours().toString().padStart(2, "0")}:${now.getMinutes().toString().padStart(2, "0")}:${now.getSeconds().toString().padStart(2, "0")}`;

  // Return the day of the week and current time
  return `${dayOfWeek}, ${time}`;
}
```

