function convertToUpperCase(str) {
  let result = '';

  for (let i = 0; i < str.length; i++) {
    const charCode = str.charCodeAt(i);
    let char = str[i];

    // Convert alphabetic characters to uppercase
    if (charCode >= 97 && charCode <= 122) {
      char = String.fromCharCode(charCode - 32);
    }
    // Convert special characters to uppercase equivalents
    else if (char === '@') {
      char = 'A';
    } else if (char === '#') {
      char = 'H';
    } else if (char === '$') {
      char = 'S';
    } else if (char === '%') {
      char = 'P';
    } else if (char === '&') {
      char = 'E';
    }

    result += char;
  }

  return result;
}

