To replace multiple occurrences of a substring in a given string with another substring in JavaScript, you can use the following code snippet:

```javascript
function replaceSubstring(string, substr1, substr2) {
  let result = '';
  let index = 0;
  while (index < string.length) {
    if (string.substr(index, substr1.length) === substr1) {
      result += substr2;
      index += substr1.length;
    } else {
      result += string[index];
      index++;
    }
  }
  return result;
}

