const express = require('express');
const rateLimit = require('express-rate-limit');

const app = express();

// Define the IP address range to allow
const allowedIPRange = '192.168.0.0/24';

// Define the user agent string to allow
const allowedUserAgent = 'MyCustomUserAgentString';

// Create a rate limiter with a maximum of 100 requests per minute
const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 100, // maximum limit
  message: 'Too Many Requests',
  statusCode: 429,
});

// Define the middleware to enforce IP address and user agent restrictions
app.use((req, res, next) => {
  const clientIP = req.ip;
  const userAgent = req.get('User-Agent');

  // Check if the client's IP is within the allowed IP range
  if (!isIPInRange(clientIP, allowedIPRange)) {
    res.status(403).send('Forbidden');
    return;
  }

  // Check if the client's user agent matches the allowed user agent string
  if (userAgent !== allowedUserAgent) {
    res.status(403).send('Forbidden');
    return;
  }

  next();
});

// Apply the rate limiter middleware
app.use(limiter);

// Define the route handler for the web server
app.get('/', (req, res) => {
  res.send('Hello, World!');
});

// Helper function to check if an IP address is within a range
function isIPInRange(ip, range) {
  const [ipAddress, subnet] = range.split('/');
  const ipBuffer = Buffer.from(ip.split('.'));
  const subnetBuffer = Buffer.alloc(4);
  subnetBuffer.writeUInt32BE(subnetToNumber(subnet), 0);
  const mask = subnetBuffer.readUInt32BE(0);
  const maskedIP = ipBuffer.readUInt32BE(0) & mask;
  const maskedNet = subnetBuffer.readUInt32BE(0) & mask;
  return maskedIP === maskedNet;
}

// Helper function to convert subnet to number
function subnetToNumber(subnet) {
  const parts = subnet.split('.').map(Number);
  return (parts[0] << 24) + (parts[1] << 16) + (parts[2] << 8) + parts[3];
}

// Start the web server on port 8080
app.listen(8080, () => {
  console.log('Web server listening on port 8080');
});
```

