      const interval = setInterval(() => {
        const now = new Date();
        const difference = countdownDateTime - now;

        if (difference <= 0) {
          clearInterval(interval);
        } else {
          setCountdown(Math.floor(difference / 1000));
        }
      }, 1000);

      return () => {
        clearInterval(interval);
      };
    }
  }, [countdownDateTime]);

  const toggleFormat = () => {
    setFormat((prevFormat) =>
      prevFormat === 'YYYY-MM-DD HH:MM:SS' ? 'DD/MM/YYYY HH:MM:SS' : 'YYYY-MM-DD HH:MM:SS'
    );
  };

  const setCustomDateTime = () => {
    const customDateTime = new Date(inputDateTime);

    if (!isNaN(customDateTime.getTime())) {
      setDateTime(customDateTime);

      if (customDateTime > new Date()) {
        setCountdownDateTime(customDateTime);
      }
    }
  };

  const handleCountdownIntervalChange = (event) => {
    const interval = parseInt(event.target.value, 10);
    setCountdownInterval(isNaN(interval) || interval < 1 ? 1 : interval);
  };

  const handleTimeZoneChange = (event) => {
    setTimeZone(event.target.value);
  };

  const formatDateTime = (dateTime) => {
    const options = {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false,
      timeZone,
    };

    return dateTime.toLocaleString(undefined, options);
  };

  return (
    <div>
      <div>{formatDateTime(dateTime)}</div>
      <button onClick={toggleFormat}>Toggle Format</button>
      <br />
      <input
        type="text"
        value={inputDateTime}
        onChange={(event) => setInputDateTime(event.target.value)}
      />
      <button onClick={setCustomDateTime}>Set Date and Time</button>
      <br />
      <input
        type="number"
        min="1"
        value={countdownInterval}
        onChange={handleCountdownIntervalChange}
      />
      <button onClick={setCustomDateTime}>Set Date and Time with Countdown</button>
      <br />
      <select value={timeZone} onChange={handleTimeZoneChange}>
        <option value="">Select Time Zone</option>
        <option value="America/New_York">America/New_York</option>
        <option value="America/Los_Angeles">America/Los_Angeles</option>
        <option value="Europe/London">Europe/London</option>
        <option value="Asia/Tokyo">Asia/Tokyo</option>
      </select>
    </div>
  );
};

export default DateTimeDisplay;
