import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';

// Redux actions
const setText = (text) => ({
  type: 'SET_TEXT',
  payload: text,
});

const clearText = () => ({
  type: 'CLEAR_TEXT',
});

const convertToUpperCase = () => ({
  type: 'CONVERT_TO_UPPERCASE',
});

const convertToLowerCase = () => ({
  type: 'CONVERT_TO_LOWERCASE',
});

const reverseText = () => ({
  type: 'REVERSE_TEXT',
});

// Redux reducer
const reducer = (state = { text: '', characterCount: 0 }, action) => {
  switch (action.type) {
    case 'SET_TEXT':
      return {
        ...state,
        text: action.payload,
        characterCount: calculateCharacterCount(action.payload),
      };
    case 'CLEAR_TEXT':
      return {
        ...state,
        text: '',
        characterCount: 0,
      };
    case 'CONVERT_TO_UPPERCASE':
      return {
        ...state,
        text: state.text.toUpperCase(),
        characterCount: calculateCharacterCount(state.text.toUpperCase()),
      };
    case 'CONVERT_TO_LOWERCASE':
      return {
        ...state,
        text: state.text.toLowerCase(),
        characterCount: calculateCharacterCount(state.text.toLowerCase()),
      };
    case 'REVERSE_TEXT':
      return {
        ...state,
        text: state.text.split('').reverse().join(''),
        characterCount: calculateCharacterCount(state.text.split('').reverse().join('')),
      };
    default:
      return state;
  }
};

// Helper function to calculate character count
const calculateCharacterCount = (text) => {
  const regex = /[aeiou\s\W]/gi; // Exclude vowels, spaces, and special characters
  const filteredText = text.replace(regex, '');
  return filteredText.length;
};

const TextAreaWithCharacterCounter = () => {
  const dispatch = useDispatch();
  const { text, characterCount } = useSelector((state) => state);

  const handleChange = (event) => {
    const newText = event.target.value;
    dispatch(setText(newText));
  };

  const handleClear = () => {
    dispatch(clearText());
  };

  const handleConvertToUpperCase = () => {
    dispatch(convertToUpperCase());
  };

  const handleConvertToLowerCase = () => {
    dispatch(convertToLowerCase());
  };

  const handleReverseText = () => {
    dispatch(reverseText());
  };

  return (
    <div>
      <textarea
        value={text}
        onChange={handleChange}
        style={{ resize: 'both' }}
      />
      <div>{characterCount}</div>
      <button onClick={handleClear}>Clear</button>
      <button onClick={handleConvertToUpperCase}>Convert to Uppercase</button>
      <button onClick={handleConvertToLowerCase}>Convert to Lowercase</button>
      <button onClick={handleReverseText}>Reverse Text</button>
    </div>
  );
};

// Redux store setup
import { createStore } from 'redux';
import { Provider } from 'react-redux';

const store = createStore(reducer);

const App = () => {
  return (
    <Provider store={store}>
      <TextAreaWithCharacterCounter />
    </Provider>
  );
};

export default App;
```

In this implementation, we have a Redux store with a reducer that handles the state for the text and character count. The `setText`, `clearText`, `convertToUpperCase`, `convertToLowerCase`, and `reverseText` actions are used to update the state based on user interactions.

The `calculateCharacterCount` function is a helper function that uses regular expressions to filter out vowels, spaces, and special characters from the text and return the remaining character count.

The `TextAreaWithCharacterCounter` component renders the textarea element, the character counter, and the buttons. The `handleChange` function dispatches the `setText` action whenever the textarea value changes. The other button click handlers dispatch their respective actions to update the state.

Finally, we set up the Redux store using the `createStore` function and wrap the `TextAreaWithCharacterCounter` component with the `Provider` component to make the store accessible throughout the component tree.

Note that you'll need to have React, Redux, and React Redux installed in your project for this implementation to work.

