function customSort(strings) {
  // Iterate through the list
  for (let i = 0; i < strings.length; i++) {
    // Store the current string and its length
    const currentString = strings[i];
    const currentStringLength = currentString.length;

    // Iterate through the list starting from the next element
    for (let j = i + 1; j < strings.length; j++) {
      // Store the compared string and its length
      const comparedString = strings[j];
      const comparedStringLength = comparedString.length;

      // Compare the lengths of the two strings
      if (currentStringLength < comparedStringLength) {
        // Swap the current string with the compared string
        strings[i] = comparedString;
        strings[j] = currentString;

        // Update the current string and its length
        currentString = comparedString;
        currentStringLength = comparedStringLength;
      }
    }
  }

  return strings;
}
```

