import random

def generate_palette(num_colors, color_type="bright", color_theme=None, gradient=False, contrast=0.5, brightness=(0.2, 0.8), saturation=(0.2, 0.8), color_model="RGB", texture=None, color_harmony=None, transparency=1.0, pleasing=True, purpose=None, distinct_hues=0, colorblind=False):
    palette = []
    hue_range = 360 // num_colors

    for i in range(num_colors):
        hue = (i * hue_range) % 360
        color = generate_random_color(hue, color_type, color_theme, gradient, contrast, brightness, saturation, color_model, texture, color_harmony, transparency, pleasing, purpose, colorblind)
        palette.append(color)

    return palette

def generate_random_color(hue, color_type, color_theme, gradient, contrast, brightness, saturation, color_model, texture, color_harmony, transparency, pleasing, purpose, colorblind):
    if color_type == "bright":
        saturation_range = (0.5, 1.0)
        brightness_range = (0.5, 1.0)
    elif color_type == "pastel":
        saturation_range = (0.2, 0.5)
        brightness_range = (0.8, 1.0)
    elif color_type == "dark":
        saturation_range = (0.2, 0.8)
        brightness_range = (0.1, 0.5)

    saturation = random.uniform(saturation_range[0], saturation_range[1])
    brightness = random.uniform(brightness_range[0], brightness_range[1])

    if color_model == "RGB":
        return generate_rgb_color(hue, saturation, brightness, transparency)
    elif color_model == "HSL":
        return generate_hsl_color(hue, saturation, brightness, transparency)
    elif color_model == "CMYK":
        return generate_cmyk_color(hue, saturation, brightness, transparency)

def generate_rgb_color(hue, saturation, brightness, transparency):
    r, g, b = hsl_to_rgb(hue / 360, saturation, brightness)
    r = int(r * 255)
    g = int(g * 255)
    b = int(b * 255)
    return f"#{r:02x}{g:02x}{b:02x}"

def generate_hsl_color(hue, saturation, brightness, transparency):
    return f"hsl({hue}, {saturation * 100}%, {brightness * 100}%)"

def generate_cmyk_color(hue, saturation, brightness, transparency):
    c, m, y, k = hsl_to_cmyk(hue / 360, saturation, brightness)
    return f"cmyk({c * 100}%, {m * 100}%, {y * 100}%, {k * 100}%)"

def hsl_to_rgb(h, s, l):
    c = (1 - abs(2 * l - 1)) * s
    x = c * (1 - abs((h / 60) % 2 - 1))
    m = l - c / 2

    if 0 <= h < 60:
        r, g, b = c, x, 0
    elif 60 <= h < 120:
        r, g, b = x, c, 0
    elif 120 <= h < 180:
        r, g, b = 0, c, x
    elif 180 <= h < 240:
        r, g, b = 0, x, c
    elif 240 <= h < 300:
        r, g, b = x, 0, c
    else:
        r, g, b = c, 0, x

    return r + m, g + m, b + m

def hsl_to_cmyk(h, s, l):
    c = (1 - abs(2 * l - 1)) * s
    x = c * (1 - abs((h / 60) % 2 - 1))
    m = l - c / 2

    if 0 <= h < 60:
        return c + m, x + m, m, 0
    elif 60 <= h < 120:
        return x + m, c + m, m, 0
    elif 120 <= h < 180:
        return m, c + m, x + m, 0
    elif 180 <= h < 240:
        return m, x + m, c + m, 0
    elif 240 <= h < 300:
        return x + m, m, c + m, 0
    else:
        return c + m, m, x + m, 0

