Here's a recursive function in JavaScript that can find the index of an element in a multi-dimensional array, even if the element is a nested array or object:

```javascript
function findElementIndex(arr, element) {
  for (let i = 0; i < arr.length; i++) {
    const currentElement = arr[i];

    if (currentElement === element) {
      return i; // Found the element, return its index
    }

    if (Array.isArray(currentElement) || typeof currentElement === 'object') {
      const nestedIndex = findElementIndex(currentElement, element);
      if (nestedIndex !== -1) {
        return [i, nestedIndex]; // Found the element in a nested array/object, return the indices
      }
    }
  }

  return -1; // Element not found
}
```

