let durations = [];
let currentDurationIndex = 0;
let countdownInterval;
let countdownPaused = false;

function startTimer() {
  if (currentDurationIndex >= durations.length) {
    console.log("Countdown finished.");
    return;
  }

  let duration = durations[currentDurationIndex];
  let countdown = duration;

  countdownInterval = setInterval(() => {
    if (countdownPaused) {
      return;
    }

    console.log(countdown);

    if (countdown === 0) {
      clearInterval(countdownInterval);
      console.log("Countdown finished.");
      currentDurationIndex++;
      startTimer();
    }

    countdown--;
  }, 2000);
}

function resetTimer() {
  clearInterval(countdownInterval);
  currentDurationIndex = 0;
  startTimer();
}

function cancelTimer() {
  clearInterval(countdownInterval);
  console.log("Countdown cancelled.");
}

function pauseResumeTimer() {
  countdownPaused = !countdownPaused;
  if (countdownPaused) {
    console.log("Countdown paused.");
  } else {
    console.log("Countdown resumed.");
  }
}

function handleKeyPress(event) {
  if (event.key === "r") {
    resetTimer();
  } else if (event.key === "c") {
    cancelTimer();
  } else if (event.key === "p") {
    pauseResumeTimer();
  }
}

function getUserInput() {
  const input = prompt("Enter durations in seconds (separated by commas):");
  durations = input.split(",").map(duration => parseInt(duration));
  startTimer();
}

