function calculateArea(width, length, numSides = 4, sideLengths = []) {
  // Validate input
  if (typeof width !== 'number' || width <= 0 ||
      typeof length !== 'number' || length <= 0 ||
      typeof numSides !== 'number' || numSides <= 0 ||
      !Array.isArray(sideLengths) ||
      numSides !== sideLengths.length ||
      !sideLengths.every(sideLength => Number.isInteger(sideLength) && sideLength > 0)) {
    return 'Invalid input';
  }

  let area;
  let perimeter;

  if (numSides === 4) {
    area = width * length;
    perimeter = 2 * (width + length);
  } else {
    // Calculate area and perimeter for irregular-shaped rooms
    let totalLength = sideLengths.reduce((acc, cur) => acc + cur, 0);
    let averageLength = totalLength / numSides;
    area = width * averageLength;
    perimeter = totalLength + 2 * width;
  }

  return { area, perimeter };
}

// Examples
