Here's a script that meets all the requirements mentioned:

```javascript
function customSort(numbers) {
  const n = numbers.length;

  // Function to swap two elements in the array
  function swap(a, b) {
    const temp = numbers[a];
    numbers[a] = numbers[b];
    numbers[b] = temp;
  }

  // Custom sorting algorithm (quicksort)
  function quicksort(low, high) {
    if (low < high) {
      // Partition the array
      const pivot = numbers[high];
      let i = low - 1;

      for (let j = low; j < high; j++) {
        if (numbers[j] < pivot || (numbers[j] === pivot && j % 2 === 0)) {
          i++;
          swap(i, j);
        }
      }

      swap(i + 1, high);

      const partitionIndex = i + 1;

      // Recursively sort the two partitions
      quicksort(low, partitionIndex - 1);
      quicksort(partitionIndex + 1, high);
    }
  }

  // Sort the array
  quicksort(0, n - 1);

  return numbers;
}

