Here's an implementation of the function in JavaScript:

```javascript
function flattenAndSort(arr, visited = new Set()) {
  const flattened = [];

  // Helper function to flatten the array
  function flatten(element) {
    if (visited.has(element)) return;
    visited.add(element);

    if (Array.isArray(element)) {
      for (let i = 0; i < element.length; i++) {
        flatten(element[i]);
      }
    } else {
      flattened.push(element);
    }
  }

  flatten(arr);

  // Remove duplicate, null, and undefined values
  const uniqueValues = Array.from(new Set(flattened.filter(value => value !== null && value !== undefined)));

  // Sort the array
  uniqueValues.sort((a, b) => {
    // Sort by data type and value
    if (typeof a !== typeof b) {
      return typeof a < typeof b ? -1 : 1;
    } else {
      if (a < b) return -1;
      if (a > b) return 1;
      return 0;
    }
  });

  return uniqueValues;
}
```

