function concatenateStrings(str1, str2) {
  // Remove whitespace from the beginning and end of the strings
  str1 = str1.trim();
  str2 = str2.trim();

  // Check if either string is empty or contains only whitespace
  if (str1.length === 0 || str2.length === 0) {
    return str1 + str2; // Return the concatenated strings as is
  }

  // Check if the last character of str1 is a special character
  var lastChar1 = str1.charAt(str1.length - 1);
  var specialChar1 = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]+/;
  if (specialChar1.test(lastChar1)) {
    return str1 + str2; // Return the concatenated strings as is
  }

  // Check if the first character of str2 is a special character
  var firstChar2 = str2.charAt(0);
  var specialChar2 = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]+/;
  if (specialChar2.test(firstChar2)) {
    return str1 + str2; // Return the concatenated strings as is
  }

  // Concatenate the strings with a space in between
  return str1 + ' ' + str2;
}

