Here is an implementation of the closure in JavaScript:

```javascript
function createClosure(str, num) {
  return function() {
    let result = str;
    const charCode = str.charCodeAt(0);
    for (let i = 0; i < charCode * num; i++) {
      result += "!";
    }
    return result;
  };
}

function invokeClosures(closures, str) {
  let result = "";
  closures.forEach(function(closure) {
    result += closure(str);
  });
  return result;
}

// Example usage:
const closure1 = createClosure("Hello", 3);
console.log(closure1()); // Output: "Hello!!!!!!!!!"

const closure2 = createClosure("Programming", 2);
console.log(closure2()); // Output: "Programming!!!!!!!!"

const closures = [closure1, closure2];
