function replaceStrings(str, oldStr, newStr) {
  let result = '';
  let stack = [];
  let brackets = [];
  let braces = [];

  for (let i = 0; i < str.length; i++) {
    let char = str[i];

    if (char === '[') {
      stack.push(char);
      brackets.push(i);
    } else if (char === ']') {
      stack.pop();
      let startIndex = brackets.pop();
      if (stack.length === 0) {
        let nestedBrackets = brackets.filter(bracket => bracket > startIndex);
        if (nestedBrackets.length === 0) {
          let substring = str.substring(startIndex, i + 1);
          if (substring.toLowerCase().includes(oldStr.toLowerCase())) {
            substring = substring.replace(new RegExp(oldStr, 'gi'), newStr);
          }
          result += substring;
        }
      }
    } else if (char === '{') {
      stack.push(char);
      braces.push(i);
    } else if (char === '}') {
      stack.pop();
      let startIndex = braces.pop();
      if (stack.length === 0) {
        let nestedBraces = braces.filter(brace => brace > startIndex);
        if (nestedBraces.length === 0) {
          let substring = str.substring(startIndex, i + 1);
          if (substring.toLowerCase().includes(oldStr.toLowerCase())) {
            substring = substring.replace(new RegExp(oldStr, 'gi'), newStr);
          }
          result += substring;
        }
      }
    } else {
      if (stack.length === 0) {
        result += char;
      }
    }
  }

  return result;
}
