function generateArray() {
  // Generate a random integer between 100 and 1000 (inclusive)
  const N = Math.floor(Math.random() * (1000 - 100 + 1)) + 100;

  // Generate an array of length N
  const arr = [];

  // Function to check if a number is prime
  const isPrime = (num) => {
    for (let i = 2, sqrt = Math.sqrt(num); i <= sqrt; i++) {
      if (num % i === 0) {
        return false;
      }
    }
    return num > 1;
  };

  // Generate random integers and ensure no two consecutive elements are equal
  let sum = 0;
  let prevNum = 0;
  for (let i = 0; i < N; i++) {
    let num;
    do {
      num = Math.floor(Math.random() * 1000) + 1;
    } while (num === prevNum);
    arr.push(num);
    sum += num;
    prevNum = num;
  }

  // Check if the sum of all elements is a prime number
  while (!isPrime(sum)) {
    // Generate a new element to replace the last one
    let num;
    do {
      num = Math.floor(Math.random() * 1000) + 1;
    } while (num === arr[N - 1]);
    arr[N - 1] = num;
    sum = sum - prevNum + num;
    prevNum = num;
  }

  return arr;
}

