```javascript
function encrypt(value, secretKey) {
  // Generate a random permutation of ASCII characters
  const permutation = generatePermutation();

  // Encrypt the value using the substitution cipher and bitwise operations
  let encryptedValue = '';
  for (let i = 0; i < value.length; i++) {
    const charCode = value.charCodeAt(i);
    const encryptedCharCode = (charCode ^ secretKey) + i * secretKey;
    encryptedValue += String.fromCharCode(permutation[encryptedCharCode % permutation.length]);
  }

  return encryptedValue;
}

function decrypt(encryptedValue, secretKey, permutation) {
  // Decrypt the value using the substitution cipher and bitwise operations
  let decryptedValue = '';
  for (let i = 0; i < encryptedValue.length; i++) {
    const encryptedCharCode = permutation.indexOf(encryptedValue.charCodeAt(i));
    const charCode = (encryptedCharCode - i * secretKey) ^ secretKey;
    decryptedValue += String.fromCharCode(charCode);
  }

  return decryptedValue;
}

function generatePermutation() {
  const asciiChars = [];
  for (let i = 0; i < 128; i++) {
    asciiChars.push(i);
  }

  // Shuffle the ASCII characters array using Fisher-Yates algorithm
  for (let i = asciiChars.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [asciiChars[i], asciiChars[j]] = [asciiChars[j], asciiChars[i]];
  }

  return asciiChars;
}

