function countOccurrences(str, char) {
  if (str.length === 0) {
    return {
      count: 0,
      indices: []
    };
  }

  const count = {};
  const indices = [];

  for (let i = 0; i < str.length; i++) {
    const currentChar = str.charAt(i);

    if (!count[currentChar]) {
      count[currentChar] = {
        count: 0,
        indices: []
      };
    }

    if (currentChar === char) {
      count[currentChar].count++;
      count[currentChar].indices.push(i);
    }
  }

  const totalCount = count[char] ? count[char].count : 0;
  const vowelList = ['a', 'e', 'i', 'o', 'u'];

  if (vowelList.includes(char.toLowerCase())) {
    totalCount--;
  }

  return {
    count: totalCount,
    indices: count[char] ? count[char].indices : []
  };
}

