```javascript
// Define an array to store the todos
let todos = [];

// Get DOM elements
const todoTable = document.getElementById("todoTable");
const searchInput = document.getElementById("searchInput");
const createTodoForm = document.getElementById("createTodoForm");
const descriptionInput = document.getElementById("descriptionInput");
const dueDateInput = document.getElementById("dueDateInput");
const footerRow = document.getElementById("footerRow");

// Function to display todos in the table
function displayTodos() {
  // Clear the table body
  todoTable.tBodies[0].innerHTML = "";

  // Loop through the todos array and add each todo to the table
  todos.forEach(function(todo) {
    const row = document.createElement("tr");
    const descriptionCell = document.createElement("td");
    const dueDateCell = document.createElement("td");
    const statusCell = document.createElement("td");

    descriptionCell.textContent = todo.description;
    dueDateCell.textContent = todo.dueDate;
    statusCell.textContent = todo.completed ? "Completed" : "Not Completed";

    row.appendChild(descriptionCell);
    row.appendChild(dueDateCell);
    row.appendChild(statusCell);
    todoTable.tBodies[0].appendChild(row);
  });

  // Update the footer row with the total number of todos and percentage completed
  const totalTodos = todos.length;
  const completedTodos = todos.filter(todo => todo.completed).length;
  const percentageCompleted = Math.round((completedTodos / totalTodos) * 100);

  footerRow.textContent = `Total Todos: ${totalTodos} | Percentage Completed: ${percentageCompleted}%`;
}

// Function to filter todos based on search query
function filterTodos(searchQuery) {
  const filteredTodos = todos.filter(todo =>
    todo.description.toLowerCase().includes(searchQuery.toLowerCase())
  );

  // Show only the rows that match the search query, hide the rest
  Array.from(todoTable.tBodies[0].rows).forEach(function(row) {
    row.style.display = filteredTodos.includes(row.textContent.trim()) ? "" : "none";
  });
}

// Event listener for search input
searchInput.addEventListener("input", function() {
  filterTodos(this.value);
});

// Event listener for create todo form submission
createTodoForm.addEventListener("submit", function(event) {
  event.preventDefault();

  // Get the values from the input fields
  const description = descriptionInput.value;
  const dueDate = dueDateInput.value;

  // Create a new todo object and add it to the todos array
  todos.push({
    description: description,
    dueDate: dueDate,
    completed: false
  });

  // Clear the input fields
  descriptionInput.value = "";
  dueDateInput.value = "";

  // Display the updated todos
  displayTodos();
});

// Event listener for marking todos as completed or not completed
todoTable.addEventListener("click", function(event) {
  const target = event.target;
  const row = target.parentNode.parentNode;
  const rowIndex = Array.from(row.parentNode.rows).indexOf(row);

  if (target.tagName === "TD" && target.cellIndex === 2) {
    todos[rowIndex].completed = !todos[rowIndex].completed;
    displayTodos();
  }
});

// Initial display of todos
displayTodos();
```

