import React, { useState } from "react";

const Button = ({ onClick, id, label, disabled, color }) => {
  const [count, setCount] = useState(0);
  const [currentColor, setCurrentColor] = useState(color[0]);

  const handleClick = () => {
    if (disabled) return;

    onClick();
    setCount(count + 1);
    const nextColorIndex = color.indexOf(currentColor) + 1;
    const nextColor = nextColorIndex === color.length ? color[0] : color[nextColorIndex];
    setCurrentColor(nextColor);

    setTimeout(() => {
      setCurrentColor(color[0]);
    }, 1000);
  };

  const handleHover = () => {
    const randomColor = `rgb(${Math.floor(Math.random() * 256)}, ${Math.floor(
      Math.random() * 256
    )}, ${Math.floor(Math.random() * 256)})`;
    setCurrentColor(randomColor);
  };

  return (
    <button
      id={id}
      onClick={handleClick}
      disabled={disabled}
      style={{ backgroundColor: currentColor }}
      onMouseOver={handleHover}
      onMouseLeave={() => setCurrentColor(color[0])}
    >
      {label} ({count})
    </button>
