BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE empId INT;
    DECLARE supervisorId INT;
    DECLARE empName VARCHAR(100);
    DECLARE supervisorName VARCHAR(100);
    DECLARE empHierarchy VARCHAR(1000);
