    OPEN empCursor;

    SET empHierarchy = '';
    read_loop: LOOP
        FETCH empCursor INTO empId, empName, empLastName, supervisorId, supervisorName, supervisorLastName;
        IF done THEN
            LEAVE read_loop;
        END IF;

        IF empHierarchy = '' THEN
            SET empHierarchy = CONCAT(empHierarchy, empName, ' ', empLastName);
        ELSE
            SET empHierarchy = CONCAT(empHierarchy, ' > ', empName, ' ', empLastName);
        END IF;

        SET empName = supervisorName;
