Here's a JavaScript function that converts a string to pig-latin while handling both upper and lower case letters, punctuation marks, and special characters. The function also returns the converted string in reverse order:

```javascript
function convertToPigLatin(str) {
  // Convert the string to lower case
  str = str.toLowerCase();

  // Split the string into an array of words
  var words = str.split(" ");

  // Define a function to convert a word to pig-latin
  function convertWord(word) {
    // Check if the word starts with a vowel
    if (/^[aeiou]/.test(word)) {
      return word + "way";
    }

    // Check if the word starts with a consonant cluster
    var consonantCluster = word.match(/^[^aeiou]+/);
    if (consonantCluster) {
      return word.slice(consonantCluster[0].length) + consonantCluster[0] + "ay";
    }

    // Return the word as it is if it doesn't match the above cases
    return word;
  }

  // Convert each word in the array to pig-latin
  var convertedWords = words.map(convertWord);

  // Reverse the array of converted words
  var reversedWords = convertedWords.reverse();

  // Join the reversed words into a string
  var result = reversedWords.join(" ");

  // Return the result
  return result;
}

// Example usage
