```java
import javax.swing.*;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;

public class StringReversalGUI extends JFrame {

    private JTextField inputField;
    private JTextArea outputArea;
    private JLabel countLabel;

    public StringReversalGUI() {
        setTitle("String Reversal");
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        setLayout(new BorderLayout());

        inputField = new JTextField();
        JButton reverseButton = new JButton("Reverse");
        outputArea = new JTextArea();
        countLabel = new JLabel();

        reverseButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                String input = inputField.getText();
                int count = reverseString(input, 0).getCount();
                outputArea.setText(reverseString(input, 0).getReversed());
                countLabel.setText("Recursive calls: " + count);
            }
        });

        JPanel inputPanel = new JPanel(new FlowLayout());
        inputPanel.add(inputField);
        inputPanel.add(reverseButton);

        add(inputPanel, BorderLayout.NORTH);
        add(new JScrollPane(outputArea), BorderLayout.CENTER);
        add(countLabel, BorderLayout.SOUTH);

        pack();
        setLocationRelativeTo(null);
    }

    private ReverseResult reverseString(String input, int count) {
        if (input.length() <= 1) {
            return new ReverseResult(input, count);
        } else {
            char firstChar = input.charAt(0);
            String restOfString = input.substring(1);
            ReverseResult result = reverseString(restOfString, count + 1);
            return new ReverseResult(result.getReversed() + firstChar, result.getCount());
        }
    }

    private static class ReverseResult {
        private String reversed;
        private int count;

        public ReverseResult(String reversed, int count) {
            this.reversed = reversed;
            this.count = count;
        }

        public String getReversed() {
            return reversed;
        }

        public int getCount() {
            return count;
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(new Runnable() {
            @Override
            public void run() {
                new StringReversalGUI().setVisible(true);
            }
        });
    }
}
```

