// Timer class
class Timer {
  constructor(duration, display) {
    this.duration = duration;
    this.display = display;
    this.timerId = null;
  }

  start() {
    // Clear any existing timer
    this.stop();

    // Set the end time
    const endTime = Date.now() + this.duration;

    // Update the timer display every second
    this.timerId = setInterval(() => {
      const remainingTime = endTime - Date.now();

      // Check if the timer has reached zero
      if (remainingTime <= 0) {
        this.stop();
        this.display.update('Timer has ended');
        return;
      }

      // Format the remaining time
      const hours = Math.floor(remainingTime / (1000 * 60 * 60)).toString().padStart(2, '0');
      const minutes = Math.floor((remainingTime % (1000 * 60 * 60)) / (1000 * 60)).toString().padStart(2, '0');
      const seconds = Math.floor((remainingTime % (1000 * 60)) / 1000).toString().padStart(2, '0');

      // Update the timer display
      this.display.update(`${hours}:${minutes}:${seconds}`);
    }, 1000);
  }

  stop() {
    clearInterval(this.timerId);
    this.timerId = null;
  }
}

// Display class
class Display {
  constructor(element) {
    this.element = element;
  }

  update(message) {
    this.element.textContent = message;
  }
