const columnDividers = document.querySelectorAll('.column-divider');
let isResizing = false;
let resizeColumn = null;
let resizeStartX = 0;

function initColumnResize(e) {
  isResizing = true;
  resizeColumn = e.target.previousElementSibling;
  resizeStartX = e.pageX;
}

function resizeColumnWidth(e) {
  if (!isResizing) return;
  const resizeDelta = e.pageX - resizeStartX;
  const newWidth = Math.max(resizeColumn.offsetWidth + resizeDelta, 10);
  const maxWidth = resizeColumn.nextElementSibling.offsetWidth - 10;
  resizeColumn.style.width = `${Math.min(newWidth, maxWidth)}px`;
}

function stopColumnResize() {
  isResizing = false;
}

