```javascript
function splitStringIntoArray(inputString) {
  let words = [];
  let currentWord = '';

  for (let i = 0; i < inputString.length; i++) {
    let currentChar = inputString[i];

    // If the current character is a space or a special character, it indicates the end of the current word
    if (currentChar === ' ' || !isLetter(currentChar)) {
      if (currentWord !== '') {
        // Convert the current word to lowercase and add it to the array, only if it's not already present
        let lowercaseWord = currentWord.toLowerCase();
        if (!words.includes(lowercaseWord)) {
          words.push(lowercaseWord);
        }
      }
      currentWord = '';
    } else {
      // Add the current character to the current word
      currentWord += currentChar;
    }
  }

  // Check if there's a word remaining after the loop ends
  if (currentWord !== '') {
    let lowercaseWord = currentWord.toLowerCase();
    if (!words.includes(lowercaseWord)) {
      words.push(lowercaseWord);
    }
  }

  return words;
}

// Helper function to check if a character is a letter (a-z or A-Z)
function isLetter(char) {
  return (char >= 'a' && char <= 'z') || (char >= 'A' && char <= 'Z');
