function sortInventory(inventory) {
  let sortedInventory = [];

  // Iterate over each category in the inventory
  for (let category in inventory) {
    let itemsToSort = [];

    // Extract items from the current category
    for (let item in inventory[category]) {
      itemsToSort.push(item);
    }

    // Sort the items alphabetically
    itemsToSort.sort();

    // Concatenate the sorted items with the sortedInventory array
    sortedInventory = sortedInventory.concat(itemsToSort);
