```python
class SudokuSolver:
    def __init__(self):
        self.grid = [[0] * 9 for _ in range(9)]
        self.possibilities = [[set(range(1, 10)) for _ in range(9)] for _ in range(9)]

    def solve(self, grid):
        self.grid = grid
        self.update_possibilities()
        self.backtrack()
        return self.grid

    def update_possibilities(self):
        for i in range(9):
            for j in range(9):
                if self.grid[i][j] != 0:
                    self.possibilities[i][j] = set()
                    self.update_possibilities_row(i, self.grid[i][j])
                    self.update_possibilities_column(j, self.grid[i][j])
                    self.update_possibilities_block(i, j, self.grid[i][j])

    def update_possibilities_row(self, row, value):
        for j in range(9):
            self.possibilities[row][j].discard(value)

    def update_possibilities_column(self, column, value):
        for i in range(9):
            self.possibilities[i][column].discard(value)

    def update_possibilities_block(self, row, column, value):
        start_row = 3 * (row // 3)
        start_column = 3 * (column // 3)
        for i in range(start_row, start_row + 3):
            for j in range(start_column, start_column + 3):
                self.possibilities[i][j].discard(value)

    def find_empty_cell(self):
        min_possibilities = float('inf')
        min_cell = None
        for i in range(9):
            for j in range(9):
                if self.grid[i][j] == 0 and len(self.possibilities[i][j]) < min_possibilities:
                    min_possibilities = len(self.possibilities[i][j])
                    min_cell = (i, j)
        return min_cell

    def backtrack(self):
        cell = self.find_empty_cell()
        if not cell:
            return True

        row, column = cell
        for value in self.possibilities[row][column]:
            self.grid[row][column] = value
            self.update_possibilities_row(row, value)
            self.update_possibilities_column(column, value)
            self.update_possibilities_block(row, column, value)

            if self.backtrack():
                return True

            self.grid[row][column] = 0
            self.update_possibilities_row(row, value)
            self.update_possibilities_column(column, value)
            self.update_possibilities_block(row, column, value)

        return False
```

