  const [searchTerm, setSearchTerm] = useState('');
  const [sortingOrder, setSortingOrder] = useState('asc');
  const [itemsPerPage, setItemsPerPage] = useState(10);
  const [currentPage, setCurrentPage] = useState(1);

  const fetchData = () => {
    // Simulate fetching data from an API
    // You can replace this with your actual data fetching logic
    const data = [
      { id: 1, name: 'Item 1', description: 'Description 1', price: 10 },
      { id: 2, name: 'Item 2', description: 'Description 2', price: 20 },
      { id: 3, name: 'Item 3', description: 'Description 3', price: 30 },
      // Add more items here
    ];
    setItems(data);
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleSearch = (e) => {
    setSearchTerm(e.target.value);
    setCurrentPage(1); // Reset current page when search term changes
  };

  const handleSortingOrderChange = (e) => {
    setSortingOrder(e.target.value);
  };

  const handleItemsPerPageChange = (e) => {
    setItemsPerPage(parseInt(e.target.value));
    setCurrentPage(1); // Reset current page when items per page changes
  };

  const handleRemoveItem = (itemId) => {
    setItems(items.filter((item) => item.id !== itemId));
  };

  // Filter items based on search term
  const filteredItems = items.filter(
    (item) =>
      item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.description.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Sort items based on sorting order
  const sortedItems = filteredItems.sort((a, b) => {
    if (sortingOrder === 'asc') {
      return a.price - b.price;
    } else {
      return b.price - a.price;
    }
  });

  // Paginate items
  const totalPages = Math.ceil(sortedItems.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const paginatedItems = sortedItems.slice(startIndex, endIndex);

