  private apiUrl = 'https://example.com/api';
  private cache: Map<string, any> = new Map<string, any>();
  private requestQueue: Map<string, Observable<any>> = new Map<string, Observable<any>>();

  private jwtToken: string;
  private tokenExpiration: number;

  constructor(private http: HttpClient) { }

  fetchData(endpoint: string): Observable<any> {
    if (this.cache.has(endpoint) && !this.isCacheExpired(endpoint)) {
      return of(this.cache.get(endpoint));
    }

    if (this.requestQueue.has(endpoint)) {
      return this.requestQueue.get(endpoint);
    }

    const requestOptions = this.getRequestOptions();

    const request = this.http.get(`${this.apiUrl}/${endpoint}`, requestOptions).pipe(
      tap((response: any) => {
        this.cache.set(endpoint, response);
        this.requestQueue.delete(endpoint);
      }),
      catchError((error: HttpErrorResponse) => {
        this.requestQueue.delete(endpoint);
        return this.handleError(error);
      })
    );

    this.requestQueue.set(endpoint, request);

    return request;
  }

