    errorMessage += 'String input cannot be empty. ';
  }

  if (!isPrime(numericInputValue)) {
    isValid = false;
    errorMessage += 'Numeric input should be a prime number.';
  }

  // Display error message if inputs are invalid
  if (!isValid) {
    alert(errorMessage);
    return;
  }

  // Calculate the sum of prime numbers
  const sum = calculateSum(numericInputValue);

  // Display the result in an alert box
  alert(`Sum of prime numbers less than or equal to ${numericInputValue}: ${sum}`);

  // Clear input fields
  stringInput.value = '';
  numericInput.value = '';
});

// Recursive function to calculate the sum of prime numbers
function calculateSum(num) {
  let sum = 0;

  for (let i = 2; i <= num; i++) {
    if (isPrime(i)) {
      sum += i;
    }
  }

  return sum;
}

// Function to check if a number is prime
function isPrime(num) {
  if (num < 2) {
    return false;
  }

  for (let i = 2; i <= Math.sqrt(num); i++) {
    if (num % i === 0) {
      return false;
    }
  }

  return true;
}
