  for (let i = 0; i < count; i++) {
    const length = getRandomNumber(minLength, maxLength);
    let str = "";
    for (let j = 0; j < length; j++) {
      const randomIndex = getRandomIndex(characters.length);
      str += characters[randomIndex];
    }
