    this.#setWidth(width);
    this.#calculateArea();
    this.#calculatePerimeter();
  }

  get area() {
    return this.#area;
  }

  get perimeter() {
    return this.#perimeter;
  }

  #setLength(length) {
    if (length <= 0) {
      throw new Error("Length should be a positive number");
    }
    this.#length = length;
  }

  #setWidth(width) {
    if (width <= 0) {
      throw new Error("Width should be a positive number");
    }
    this.#width = width;
  }

  #calculateArea() {
    this.#area = +(this.#length * this.#width).toFixed(2);
  }

  #calculatePerimeter() {
    this.#perimeter = +(2 * (this.#length + this.#width)).toFixed(2);
  }

  isSquare() {
    return this.#length === this.#width;
  }

  setDimensions(length, width) {
    this.#setLength(length);
    this.#setWidth(width);
    this.#calculateArea();
    this.#calculatePerimeter();
  }

  getDiagonalLength() {
    return +(Math.sqrt(this.#length ** 2 + this.#width ** 2)).toFixed(2);
  }
}

