function reverseArray(arr) {
  let start = 0;
  let end = arr.length - 1;

  while (start < end) {
    if (Array.isArray(arr[start]) && Array.isArray(arr[end])) {
      // If both elements are arrays, reverse them recursively
      reverseArray(arr[start]);
      reverseArray(arr[end]);
    } else {
      // Swap the elements
      let temp = arr[start];
      arr[start] = arr[end];
      arr[end] = temp;
    }

    start++;
    end--;
  }

  return arr;
}
```

