export function searchArray(array, keyword) {
    let left = 0, right = array.length - 1;

    while (left <= right) {
        const mid = Math.floor((left + right) / 2);
        if (array[mid] === keyword) {
            return [mid];
        } else if (array[mid] < keyword) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    return [];
}

