  const [explodedSlices, setExplodedSlices] = useState([]);

  const total = data.reduce((acc, { value }) => acc + value, 0);

  const handleSliceHover = (index) => {
    setHoveredSlice(index);
  };

  const handleSliceClick = (index) => {
    if (explodedSlices.includes(index)) {
      setExplodedSlices(explodedSlices.filter((i) => i !== index));
    } else {
      setExplodedSlices([...explodedSlices, index]);
    }
  };

