          const isExploded = explodedSlices.includes(index);
          const isHovered = hoveredSlice === index;

          const startAngle = (Math.PI * 2 * sliceOffset) / total;
          const endAngle = (Math.PI * 2 * (sliceOffset + value)) / total;
          const midAngle = (startAngle + endAngle) / 2;

          const x1 = 200 + Math.cos(startAngle) * (isExploded ? 50 : 0);
          const y1 = 200 + Math.sin(startAngle) * (isExploded ? 50 : 0);
          const x2 = 200 + Math.cos(endAngle) * (isExploded ? 50 : 0);
          const y2 = 200 + Math.sin(endAngle) * (isExploded ? 50 : 0);

          const slicePath = `M200,200 L${x1},${y1} A${isExploded ? 50 : 100},${isExploded ? 50 : 100} 0 ${(endAngle - startAngle) > Math.PI ? 1 : 0},1 ${x2},${y2} Z`;

          const tooltipX = 200 + Math.cos(midAngle) * 100;
          const tooltipY = 200 + Math.sin(midAngle) * 100;

          return (
            <g key={index}>
              <path
                d={slicePath}
                fill={color}
                onMouseEnter={() => handleSliceHover(index)}
                onMouseLeave={() => handleSliceHover(null)}
                onClick={() => handleSliceClick(index)}
              />
              {isHovered && (
                <text x={tooltipX} y={tooltipY} textAnchor="middle">
                  {`${label}: ${value} (${((value / total) * 100).toFixed(2)}%)`}
