function addNumbersReverse(num1, num2) {
  // Check if the input numbers are valid positive integers
  if (!Number.isInteger(num1) || !Number.isInteger(num2) || num1 < 0 || num2 < 0) {
    return 'Invalid input. Please provide valid positive integers.';
  }

  // Convert the numbers to strings and reverse them
  let strNum1 = String(num1).split('').reverse().join('');
  let strNum2 = String(num2).split('').reverse().join('');

  // Check if the numbers have the same number of digits
  if (strNum1.length !== strNum2.length) {
    return 'Input numbers must have the same number of digits.';
  }

  // Convert the reversed strings back to numbers and add them
  let sum = Number(strNum1) + Number(strNum2);

  // Check if the sum is a decimal number
  if (sum % 1 !== 0) {
    return sum.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2});
  }

  // Convert the sum to a string and reverse it
  let strSum = String(sum).split('').reverse().join('');

  // Add commas every three digits
  let formattedSum = '';
  for (let i = 0; i < strSum.length; i++) {
    formattedSum += strSum[i];
    if ((i + 1) % 3 === 0 && i !== strSum.length - 1) {
      formattedSum += ',';
    }
  }

  return formattedSum;
}

