function pythagoreanTriplets(x) {
  if (x < 0) {
    return [];
  }

  const triplets = [];

  for (let a = 1; a < x; a++) {
    for (let b = a + 1; b < x; b++) {
      const c = Math.sqrt(a * a + b * b);
      if (c % 1 === 0 && a + b + c === x && !isPerfectSquare(a * a + b * b + c * c)) {
        triplets.push([a, b, c]);
      }
    }
  }

  return triplets;
}

