Here is a JavaScript algorithm to check if an array of numbers is sorted in ascending order and does not contain any duplicate elements without using any built-in array methods such as sort() or reverse():

```javascript
function isSortedAndUnique(arr) {
  // Check if the array is empty or has only one element
  if (arr.length <= 1) {
    return true;
  }

  // Sort the array using a merge sort algorithm
  function mergeSort(arr) {
    if (arr.length <= 1) {
      return arr;
    }

    const mid = Math.floor(arr.length / 2);
    const left = mergeSort(arr.slice(0, mid));
    const right = mergeSort(arr.slice(mid));

    return merge(left, right);
  }

  function merge(left, right) {
    const merged = [];
    let leftIndex = 0;
    let rightIndex = 0;

    while (leftIndex < left.length && rightIndex < right.length) {
      if (left[leftIndex] < right[rightIndex]) {
        merged.push(left[leftIndex]);
        leftIndex++;
      } else {
        merged.push(right[rightIndex]);
        rightIndex++;
      }
    }

    return merged.concat(left.slice(leftIndex)).concat(right.slice(rightIndex));
  }

  const sortedArr = mergeSort(arr);

  // Check if the sorted array has any duplicate elements
  for (let i = 0; i < sortedArr.length - 1; i++) {
    if (sortedArr[i] === sortedArr[i + 1]) {
      return false;
    }
  }

  return true;
}

// Example usage
console.log(isSortedAndUnique([1, 2, 3, 4, 5])); // Output: true
console.log(isSortedAndUnique([1, 2, 3, 4, 4])); // Output: false
