    if (!compareFn) {
      compareFn = (a, b) => a - b;
    }

    const sortedArr = mergeSort(arr.slice(), compareFn);
    arr.length = 0;
    arr.push(...sortedArr);
  }

  function sortDescending(arr, compareFn) {
    if (!compareFn) {
      compareFn = (a, b) => a - b;
    }

    const sortedArr = mergeSort(arr.slice(), (a, b) => compareFn(b, a));
    arr.length = 0;
    arr.push(...sortedArr);
  }

  function sortSubarray(arr, start, end, compareFn) {
    if (!compareFn) {
      compareFn = (a, b) => a - b;
    }

    const subarray = arr.slice(start, end + 1);
    const sortedSubarray = mergeSort(subarray, compareFn);

    for (let i = start; i <= end; i++) {
      arr[i] = sortedSubarray[i - start];
    }
  }

