```sql
CREATE PROCEDURE insert_user_preferences(
    IN user_id INT,
    IN preference_values JSON
)
BEGIN
    DECLARE preference_name VARCHAR(255);
    DECLARE preference_value VARCHAR(255);

    DECLARE done INT DEFAULT FALSE;
    DECLARE cur CURSOR FOR SELECT JSON_UNQUOTE(JSON_EXTRACT(preference_values, CONCAT('$."', preference_name, '"'))) AS preference_value;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    OPEN cur;

    read_loop: LOOP
        FETCH cur INTO preference_value;
        IF done THEN
            LEAVE read_loop;
        END IF;

        INSERT INTO user_preferences (user_id, preference_name, preference_value, timestamp)
        VALUES (user_id, preference_name, preference_value, NOW())
        ON DUPLICATE KEY UPDATE preference_value = preference_value, timestamp = NOW();
    END LOOP;

    CLOSE cur;
END;
