function capitalizeWords(phrase) {
  const words = phrase.split(' ');

  for (let i = 0; i < words.length; i++) {
    let word = words[i];

    // Remove any punctuation marks at the end of each word
    word = word.replace(/[^\w\s]|_/g, '').replace(/\s+/g, ' ');

