function multiply(a, b) {
  // Handle the case when either a or b is 0
  if (a === 0 || b === 0) {
    return 0;
  }

  // Handle the case when either a or b is negative
  if (a < 0 && b < 0) {
    // Both a and b are negative, so the result is positive
    a = -a;
    b = -b;
  } else if (a < 0 || b < 0) {
    // Either a or b is negative, so the result is negative
    a = Math.abs(a);
    b = Math.abs(b);
    return -multiply(a, b);
  }

  // Recursive function to calculate the product
  function multiplyRecursive(a, b) {
    if (b === 1) {
      return a;
    }

    if (b % 2 === 0) {
      // b is even
      const half = multiplyRecursive(a, b / 2);
      return half + half;
    } else {
      // b is odd
      const half = multiplyRecursive(a, Math.floor(b / 2));
      return half + half + a;
    }
  }

  return multiplyRecursive(a, b);
}
```

