function containsAllVowels(sentence) {
  const vowels = ['a', 'e', 'i', 'o', 'u'];
  const vowelCounts = new Array(5).fill(0);

  for (let i = 0; i < sentence.length; i++) {
    const char = sentence[i];
    const vowelIndex = vowels.indexOf(char.toLowerCase());

    if (vowelIndex !== -1) {
      vowelCounts[vowelIndex]++;
    }
  }

  let prevIndex = -1;
  for (let i = 0; i < vowelCounts.length; i++) {
    if (vowelCounts[i] === 0) {
      return false;
    }
    if (i > 0 && vowelCounts[i] < vowelCounts[i - 1]) {
      return false;
    }
    if (vowelCounts[i] > 1 && i <= prevIndex) {
      return false;
    }
    prevIndex = i;
  }

  return true;
}

