            constructor(x, y, mass, radius, color) {
                this.x = x;
                this.y = y;
                this.mass = mass;
                this.radius = radius;
                this.color = color;
                this.vx = Math.random() * 2 - 1;
                this.vy = Math.random() * 2 - 1;
            }

            draw(ctx) {
                ctx.beginPath();
                ctx.arc(this.x, this.y, this.radius, 0, 2 * Math.PI);
                ctx.fillStyle = this.color;
                ctx.fill();
