            const body = new CelestialBody(x, y, mass, radius, color);
            bodies.push(body);
        }

        // Simulation loop
        function loop() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            for (let body of bodies) {
                body.applyGravity(bodies);
                body.update();
                body.draw(ctx);

                if (body.x < 0 || body.x > canvas.width || body.y < 0 || body.y > canvas.height) {
                    body.vx *= -1;
                    body.vy *= -1;
                }

                if (body.checkCollision(bodies)) {
                    body.vx *= -1;
                    body.vy *= -1;
                }
            }

            requestAnimationFrame(loop);
        }

        loop();
    </script>
</body>
</html>
```

