function checkKey(obj, key) {
  // Base case: if obj is not an object or we have reached the fifth level, return false
  if (typeof obj !== 'object' || Object.keys(obj).length === 0 || Object.keys(obj).length < 5) {
    return false;
  }

  // Recursive case: iterate through each key in obj
  for (const nestedKey in obj) {
    // Check if the current key is equal to the specified key
    if (nestedKey === key) {
      return true;
    }

    // Check the next level by recursively calling the function with the current value
    if (typeof obj[nestedKey] === 'object' && Object.keys(obj[nestedKey]).length >= 5) {
      const result = checkKey(obj[nestedKey], key);
      if (result) {
        return true;
      }
    }
  }

  return false; // Key not found at the fifth level
}
