Here's an implementation of the function that parses an HTML document and finds all elements with the given class name using JavaScript:

```javascript
function getElementsByClassName(html, className) {
  const elements = [];

  function traverseNodes(node) {
    if (node.nodeType === Node.ELEMENT_NODE) {
      const classList = node.classList;
      if (classList.contains(className)) {
        elements.push(node);
      }
      if (classList.length > 0) {
        for (let i = 0; i < classList.length; i++) {
          if (classList[i].includes(className)) {
            elements.push(node);
            break;
          }
        }
      }
    }

    node = node.firstChild;
    while (node) {
      traverseNodes(node);
      node = node.nextSibling;
    }
  }

  const doc = new DOMParser().parseFromString(html, "text/html");
  traverseNodes(doc.body);

  return elements;
}
```

