```javascript
const API_URL = 'https://example.com/api/images';
const CACHE = {};

let currentPage = 1;
let totalPages = 1;

function fetchImages(page) {
    if (CACHE[page]) {
        return Promise.resolve(CACHE[page]);
    } else {
        return fetch(`${API_URL}?page=${page}&limit=12`)
            .then(response => response.json())
            .then(images => {
                CACHE[page] = images;
                return images;
            });
    }
}

function renderImages(images) {
    const gridContainer = document.getElementById('imageGrid');
    gridContainer.innerHTML = '';

    images.forEach(image => {
        const gridItem = document.createElement('div');
        gridItem.className = 'grid-item';

        const img = document.createElement('img');
        img.src = image.url;

        gridItem.appendChild(img);
        gridContainer.appendChild(gridItem);
    });
}

function updatePaginationButtons() {
    const previousBtn = document.getElementById('previousBtn');
    const nextBtn = document.getElementById('nextBtn');

    previousBtn.disabled = currentPage === 1;
    nextBtn.disabled = currentPage === totalPages;
}

function loadImages(page) {
    fetchImages(page)
        .then(images => {
            renderImages(images);
            updatePaginationButtons();
        })
        .catch(error => {
            console.error('Error:', error);
        });
}

document.getElementById('previousBtn').addEventListener('click', () => {
    if (currentPage > 1) {
        currentPage--;
        loadImages(currentPage);
    }
});

document.getElementById('nextBtn').addEventListener('click', () => {
    if (currentPage < totalPages) {
        currentPage++;
        loadImages(currentPage);
    }
});

fetch(`${API_URL}/count`)
    .then(response => response.json())
    .then(count => {
        totalPages = Math.ceil(count / 12);
        loadImages(currentPage);
    })
    .catch(error => {
        console.error('Error:', error);
    });
```

In this example, the images are fetched from the API using the `fetchImages` function. The fetched images are then stored in the `CACHE` object to minimize API calls. The `renderImages` function dynamically creates the grid items and appends them to the grid container. The `updatePaginationButtons` function disables the "Previous" and "Next" buttons when necessary. The `loadImages` function is called when the page is loaded and when the "Previous" or "Next" button is clicked.

