Sure! Here's an example of how you can create a Node.js server that serves a static HTML page and implements the specified routes for displaying the current time and managing user-specific tasks.

First, make sure you have Node.js and a database (such as MongoDB) installed on your machine. Then, follow these steps:

1. Create a new directory for your project and navigate to it in your terminal.
2. Run `npm init` to initialize a new Node.js project. Follow the prompts to set up your project.
3. Install the necessary dependencies by running the following commands:
```
npm install express mongoose body-parser bcrypt jsonwebtoken moment
```

Now, let's start building our server.

1. Create a new file called `server.js` and open it in your preferred code editor.
2. Require the necessary modules at the top of the file:
```javascript
const express = require('express');
const bodyParser = require('body-parser');
const mongoose = require('mongoose');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const moment = require('moment');
```
3. Create an instance of the Express application:
```javascript
const app = express();
```
4. Set up middleware to parse JSON bodies:
```javascript
app.use(bodyParser.json());
```
5. Connect to your MongoDB database:
```javascript
mongoose.connect('mongodb://localhost/tasksDB', { useNewUrlParser: true, useUnifiedTopology: true });
```
6. Create a schema for the tasks and sub-tasks:
```javascript
const taskSchema = new mongoose.Schema({
  name: String,
  description: String,
  dueDate: Date,
  priority: String,
  subTasks: [{
    name: String,
    description: String,
    dueDate: Date,
    priority: String
  }]
});

const Task = mongoose.model('Task', taskSchema);
```
7. Set up authentication and authorization middleware. For simplicity, we'll use hardcoded usernames and passwords, but you can replace them with a more secure mechanism in a real-world application:
```javascript
app.use((req, res, next) => {
  const token = req.headers.authorization;
  if (!token) {
    return res.status(401).json({ message: 'Authentication failed.' });
  }

  try {
    const decoded = jwt.verify(token, 'secretKey');
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(401).json({ message: 'Authentication failed.' });
  }
});
```
8. Implement the route for displaying the current time in a specific timezone. You can replace 'America/New_York' with your desired timezone:
```javascript
app.get('/current-time', (req, res) => {
  const currentTime = moment().tz('America/New_York').format('YYYY-MM-DD HH:mm:ss');
  res.send(`The current time is: ${currentTime}`);
});
```
9. Implement the REST API endpoints for creating, retrieving, updating, and deleting tasks:
```javascript
// Create a task
app.post('/tasks', (req, res) => {
  const task = new Task(req.body);
  task.save((err, savedTask) => {
    if (err) {
      return res.status(500).json({ message: 'Failed to create task.' });
    }
    res.status(201).json(savedTask);
  });
});

// Retrieve all tasks
app.get('/tasks', (req, res) => {
  Task.find((err, tasks) => {
    if (err) {
      return res.status(500).json({ message: 'Failed to retrieve tasks.' });
    }
    res.json(tasks);
  });
});

// Retrieve a specific task by ID
app.get('/tasks/:id', (req, res) => {
  Task.findById(req.params.id, (err, task) => {
    if (err) {
      return res.status(500).json({ message: 'Failed to retrieve task.' });
    }
    if (!task) {
      return res.status(404).json({ message: 'Task not found.' });
    }
    res.json(task);
  });
});

// Update a specific task by ID
app.put('/tasks/:id', (req, res) => {
  Task.findByIdAndUpdate(req.params.id, req.body, { new: true }, (err, updatedTask) => {
    if (err) {
      return res.status(500).json({ message: 'Failed to update task.' });
    }
    if (!updatedTask) {
      return res.status(404).json({ message: 'Task not found.' });
    }
    res.json(updatedTask);
  });
});

// Delete a specific task by ID
app.delete('/tasks/:id', (req, res) => {
  Task.findByIdAndRemove(req.params.id, (err, deletedTask) => {
    if (err) {
      return res.status(500).json({ message: 'Failed to delete task.' });
    }
    if (!deletedTask) {
      return res.status(404).json({ message: 'Task not found.' });
    }
    res.json(deletedTask);
  });
});
```
10. Start the server:
```javascript
app.listen(3000, () => {
  console.log('Server started on port 3000');
});
```

