  // Check if inputs are valid
  if (typeof x !== 'number' || typeof y !== 'number' || x < 0 || y < 0 || !Number.isInteger(x) || !Number.isInteger(y)) {
    throw new Error('Invalid inputs. Please provide positive integer values for x and y.');
