  const halfLength = Math.floor(length / 2);

  let randomString = '';

  // Generate unique uppercase characters
  for (let i = 0; i < halfLength; i++) {
    const randomIndex = Math.floor(Math.random() * 26);
    const randomChar = chars[randomIndex].toUpperCase();
    randomString += randomChar;
  }

  // Generate unique lowercase characters
  for (let i = 0; i < halfLength; i++) {
    const randomIndex = Math.floor(Math.random() * 26);
    const randomChar = chars[randomIndex];
    randomString += randomChar;
  }

  // Shuffle the string
  randomString = shuffleString(randomString);

  return randomString;
}

function shuffleString(string) {
  let shuffledString = '';

  while (string.length > 0) {
    const randomIndex = Math.floor(Math.random() * string.length);
    const char = string[randomIndex];
    shuffledString += char;
    string = string.slice(0, randomIndex) + string.slice(randomIndex + 1);
  }

  return shuffledString;
}

