Here is a recursive JavaScript function that determines if a given number is prime within the range of -1000 to 1000. It also calculates and outputs the factorial of the given number if it is not a prime number:

```javascript
function isPrime(num) {
  // Check if number is within the range
  if (num < -1000 || num > 1000) {
    return "INVALID";
  }

  // Check if number is negative and convert it to positive
  if (num < 0) {
    num = -num;
  }

  // Base cases
  if (num === 0 || num === 1) {
    return "Not prime";
  }

  // Recursive case
  function isPrimeRecursive(n, divisor) {
    if (divisor === 1) {
      return "Prime";
    }

    if (n % divisor === 0) {
      return n + "! = " + calculateFactorial(n);
    }

    return isPrimeRecursive(n, divisor - 1);
  }

  // Calculate factorial of a number
  function calculateFactorial(n) {
    if (n === 0) {
      return 1;
    }

    return n * calculateFactorial(n - 1);
  }

  return isPrimeRecursive(num, Math.floor(Math.sqrt(num)));
}

// Example usage
console.log(isPrime(7)); // Output: "Prime"
console.log(isPrime(10)); // Output: "10! = 3628800"
console.log(isPrime(-5)); // Output: "5! = 120"
console.log(isPrime(2000)); // Output: "INVALID"
```

