import React, { useState, useEffect } from 'react';

const CountdownTimer = () => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [countdown, setCountdown] = useState(10 * 60 * 1000); // 10 minutes in milliseconds

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentDate(new Date());
    }, 1);

    return () => {
      clearInterval(timer);
    };
  }, []);

  useEffect(() => {
    const countdownTimer = setInterval(() => {
      setCountdown((prevCountdown) => {
        if (prevCountdown > 0) {
          return prevCountdown - 1;
        } else {
          clearInterval(countdownTimer);
          return 0;
        }
      });
    }, 1);

    return () => {
      clearInterval(countdownTimer);
    };
  }, []);

  const formatTime = (date) => {
    const dayOfWeek = date.toLocaleDateString('en-US', { weekday: 'long' });
    const month = date.toLocaleDateString('en-US', { month: 'long' });
    const day = date.toLocaleDateString('en-US', { day: 'numeric' });
    const year = date.getFullYear();
    const hour = date.getHours().toString().padStart(2, '0');
    const minute = date.getMinutes().toString().padStart(2, '0');
    const second = date.getSeconds().toString().padStart(2, '0');

    return `${dayOfWeek}, ${month} ${day}, ${year} - ${hour}:${minute}:${second}`;
  };

  const formatCountdown = (countdown) => {
    const minutes = Math.floor(countdown / (60 * 1000)).toString().padStart(2, '0');
    const seconds = Math.floor((countdown % (60 * 1000)) / 1000).toString().padStart(2, '0');

    return `${minutes}:${seconds}`;
  };

  return (
    <div>
      <div>{formatTime(currentDate)}</div>
      {countdown > 0 ? (
        <div>{formatCountdown(countdown)}</div>
      ) : (
        <div>Time's up!</div>
      )}
    </div>
  );
};

export default CountdownTimer;

Here is the JavaScript function that meets the given requirements:

```javascript
function longestPalindrome(s) {
  let maxLength = 0;
  let start = 0;

  for (let i = 0; i < s.length; i++) {
    // Find the longest odd length palindrome
    let left = i;
    let right = i;
    while (left >= 0 && right < s.length && s[left] === s[right]) {
      const length = right - left + 1;
      if (length > maxLength) {
        maxLength = length;
        start = left;
      }
      left--;
      right++;
    }

    // Find the longest even length palindrome
    left = i;
    right = i + 1;
    while (left >= 0 && right < s.length && s[left] === s[right]) {
      const length = right - left + 1;
      if (length > maxLength) {
        maxLength = length;
        start = left;
      }
      left--;
      right++;
    }
  }

  return s.slice(start, start + maxLength);
}
```

Example usage:

```javascript
console.log(longestPalindrome("babad")); // "bab"
console.log(longestPalindrome("cbbd")); // "bb"
console.log(longestPalindrome("a")); // "a"
console.log(longestPalindrome("ac")); // "a"
```

