In addition to finding the greatest common divisor, the script should also calculate the least common multiple of the two numbers.

Please provide the script in a single function named "findGCDandLCM" which takes two parameters: "num1" and "num2" representing the two numbers. The function should return an object with two properties: "gcd" for the greatest common divisor and "lcm" for the least common multiple.

Note: The script should handle negative numbers as well.

Example usage:
findGCDandLCM(10, 15);
// Returns: {gcd: 5, lcm: 30}

findGCDandLCM(-12, 18);
// Returns: {gcd: 6, lcm: 36}

function findGCDandLCM(num1, num2) {
  // Check if either number is 0, in which case the GCD is the non-zero number and the LCM is 0
  if (num1 === 0) {
    return { gcd: Math.abs(num2), lcm: 0 };
  }
  if (num2 === 0) {
    return { gcd: Math.abs(num1), lcm: 0 };
  }

  // Find the absolute values of the numbers for easier calculations
  const absNum1 = Math.abs(num1);
  const absNum2 = Math.abs(num2);

  // Find the GCD using the Euclidean algorithm
  let remainder;
  let gcd = absNum1;
  let lcm = (absNum1 * absNum2) / gcd;

  while (absNum2 !== 0) {
    remainder = gcd % absNum2;
    gcd = absNum2;
    absNum2 = remainder;
  }

  // Calculate the LCM using the formula: LCM = (absNum1 * absNum2) / GCD
  lcm = (absNum1 * absNum2) / gcd;

  // Return the GCD and LCM as an object
  return { gcd, lcm };
}

