function reverseString(text) {
  let reversedText = "";
  let i = text.length - 1;

  while (i >= 0) {
    if (isPunctuation(text[i]) || isSpecialCharacter(text[i]) || isWhitespace(text[i])) {
      reversedText += text[i];
    } else {
      let j = i;
      while (j >= 0 && !isPunctuation(text[j]) && !isSpecialCharacter(text[j]) && !isWhitespace(text[j])) {
        j--;
      }
      let word = text.substring(j + 1, i + 1);
      reversedText += reverseWord(word);
      i = j;
    }
    i--;
  }

  return reversedText;
}

