class NumberUtil {
  public static findTwoLargestPrimes(numbers: number[]): number {
    if (numbers.length < 2) {
      throw new Error('Input array must contain at least 2 numbers');
    }

    let largestPrime = -Infinity;
    let secondLargestPrime = -Infinity;

    for (let i = 0; i < numbers.length; i++) {
      if (NumberUtil.isPrime(numbers[i])) {
        if (numbers[i] > largestPrime) {
          secondLargestPrime = largestPrime;
          largestPrime = numbers[i];
        } else if (numbers[i] > secondLargestPrime) {
          secondLargestPrime = numbers[i];
        }
      }
    }

    if (largestPrime === -Infinity || secondLargestPrime === -Infinity) {
      throw new Error('No prime numbers found in the array');
    }

    return largestPrime * secondLargestPrime;
  }

  private static isPrime(num: number): boolean {
    if (num <= 1) {
      return false;
    }

    if (num === 2) {
      return true;
    }

    if (num % 2 === 0) {
      return false;
    }

    const sqrtNum = Math.sqrt(num);
    for (let i = 3; i <= sqrtNum; i += 2) {
      if (num % i === 0) {
        return false;
      }
    }

    return true;
  }
}
