import java.io.FileWriter;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class PrimeNumberMultiplicationTable {
    private static final int MAX_DIMENSION = 10;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter the dimensions of the multiplication table (e.g., 5x5): ");
        String dimensionsString = scanner.nextLine();
        scanner.close();

        int rows, columns;
        try {
            String[] dimensions = dimensionsString.split("x");
            rows = Integer.parseInt(dimensions[0]);
            columns = Integer.parseInt(dimensions[1]);

            if (rows <= 0 || columns <= 0) {
                throw new IllegalArgumentException("Dimensions must be positive integers.");
            }
        } catch (Exception e) {
            System.out.println("Invalid input: " + e.getMessage());
            return;
        }

        int[][] multiplicationTable = generateMultiplicationTable(rows, columns);

        System.out.println("Prime Number Multiplication Table:");
        displayTable(multiplicationTable);

        System.out.println("Export the table to a file? (y/n)");
        scanner = new Scanner(System.in);
        String exportChoice = scanner.nextLine().toLowerCase();
        scanner.close();

        if (exportChoice.equals("y")) {
            exportTableToFile(multiplicationTable, dimensionsString);
        }
    }

    private static int[][] generateMultiplicationTable(int rows, int columns) {
        int[][] table = new int[rows][columns];

        int number = 2;
        int currentRow = 0, currentColumn = 0;
        while (currentRow < rows) {
            if (isPrime(number)) {
                table[currentRow][currentColumn] = number;
                currentColumn++;

                if (currentColumn == columns) {
                    currentRow++;
                    currentColumn = 0;
                }
            }
            number++;
        }
        return table;
    }

    private static boolean isPrime(int number) {
        if (number < 2) {
            return false;
        }
        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }
        return true;
    }

    private static void displayTable(int[][] table) {
        for (int[] row : table) {
            for (int number : row) {
                System.out.printf("%-5d", number);
            }
            System.out.println();
        }
    }

    private static void exportTableToFile(int[][] table, String dimensionsString) {
        FileWriter writer = null;
        try {
            writer = new FileWriter("prime_table_" + dimensionsString + ".txt");
            for (int[] row : table) {
                for (int number : row) {
                    writer.write(number + "\t");
                }
                writer.write("\n");
            }
            writer.close();
            System.out.println("Table exported successfully.");
        } catch (IOException e) {
            System.out.println("Error exporting table to file: " + e.getMessage());
        } finally {
            try {
                if (writer != null) {
                    writer.close();
                }
            } catch (IOException e) {
                System.out.println("Error closing file writer: " + e.getMessage());
            }
        }
    }
}
