class ManipulateData {
  constructor(number, string, objects, bool) {
    if (typeof number !== 'number' || isNaN(number)) {
      throw new Error('Invalid number argument');
    }
    if (typeof string !== 'string') {
      throw new Error('Invalid string argument');
    }
    if (!Array.isArray(objects) || objects.length === 0) {
      throw new Error('Invalid array of objects argument');
    }
    if (typeof bool !== 'boolean') {
      throw new Error('Invalid boolean argument');
    }

    this.number = number;
    this.string = string;
    this.objects = objects;
    this.bool = bool;
  }

  manipulateData() {
    let modifiedNumber;
    let modifiedString;
    let sortedObjects;

    if (this.bool) {
      if (this.number % 2 === 0) {
        modifiedNumber = this.number * 3 + 5;
      } else {
        modifiedNumber = (this.number - 7) / 2;
      }
    }

    if (this.bool === false) {
      modifiedString = this.string.concat(this.string)
                                 .split('')
                                 .reverse()
                                 .join('')
                                 .toUpperCase();
    }

    if (this.objects.every(obj => obj.hasOwnProperty('name'))) {
      sortedObjects = this.objects.sort((a, b) => a.name.localeCompare(b.name));
    } else {
      throw new Error('Invalid array of objects: missing "name" property');
    }

    return {
      modifiedNumber,
      modifiedString,
      sortedObjects
    };
  }
}

