function isDivisibleByFourAndSeven(num) {
  if (num === 0) {
    return false;
  }

  if (num === 4 || num === 7) {
    return true;
  }

  return isDivisibleByFourAndSeven(num - 4) || isDivisibleByFourAndSeven(num - 7);
}
